import { createClient } from '@supabase/supabase-js'
import { ENV_CONFIG, validateEnvironment } from './env-config'

// Validate environment on initialization
validateEnvironment();

// 创建客户端，确保配置有效
export const supabase = createClient(ENV_CONFIG.SUPABASE_URL, ENV_CONFIG.SUPABASE_ANON_KEY, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  },
  global: {
    headers: {
      'x-application-name': 'anime-social-app',
    },
  },
})

// 导出配置供调试使用
export const supabaseConfig = {
  url: ENV_CONFIG.SUPABASE_URL,
  hasValidConfig: true,
  isUsingDefaults: ENV_CONFIG.SUPABASE_URL === 'https://nzksnfoxrzzkoppcehpe.supabase.co',
  appName: ENV_CONFIG.APP_NAME,
  environment: ENV_CONFIG.APP_ENV,
}