import { useState } from 'react'
import { Heart, MessageCircle, Bookmark, Share2, X } from 'lucide-react'
import { Post } from '../types'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { CommentSection } from './CommentSection'

interface PostDetailModalProps {
  post: Post
  isOpen: boolean
  onClose: () => void
}

export function PostDetailModal({ post, isOpen, onClose }: PostDetailModalProps) {
  const [isLiked, setIsLiked] = useState(post.is_liked)
  const [isFavorited, setIsFavorited] = useState(post.is_favorited)
  const [likesCount, setLikesCount] = useState(post.likes_count)
  const [comments, setComments] = useState(post.comments || [])
  const [isLoading, setIsLoading] = useState(false)
  const [currentImageIndex, setCurrentImageIndex] = useState(0)

  if (!isOpen) return null

  const handleLike = async () => {
    try {
      setIsLoading(true)
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        toast.error('请先登录')
        return
      }

      if (isLiked) {
        const { error } = await supabase
          .from('likes')
          .delete()
          .eq('user_id', user.id)
          .eq('post_id', post.id)
        
        if (error) throw error
        setIsLiked(false)
        setLikesCount(prev => prev - 1)
        toast.success('取消点赞')
      } else {
        const { error } = await supabase
          .from('likes')
          .insert({
            user_id: user.id,
            post_id: post.id
          })
        
        if (error) throw error
        setIsLiked(true)
        setLikesCount(prev => prev + 1)
        toast.success('点赞成功')
      }
    } catch (error) {
      toast.error('操作失败')
    } finally {
      setIsLoading(false)
    }
  }

  const handleFavorite = async () => {
    try {
      setIsLoading(true)
      if (isFavorited) {
        // 取消收藏逻辑
        setIsFavorited(false)
        toast.success('取消收藏')
      } else {
        // 收藏逻辑
        setIsFavorited(true)
        toast.success('收藏成功')
      }
    } catch (error) {
      toast.error('操作失败')
    } finally {
      setIsLoading(false)
    }
  }

  const handleCommentAdded = (newComment: any) => {
    setComments(prev => [...prev, newComment])
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden">
        {/* 头部 */}
        <div className="flex items-center justify-between p-6 border-b">
          <div className="flex items-center space-x-3">
            <img
              src={post.user.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${post.user.username}`}
              alt={post.user.username}
              className="w-10 h-10 rounded-full object-cover"
            />
            <div>
              <h3 className="font-semibold text-gray-800">{post.user.username}</h3>
              <p className="text-sm text-gray-500">
                {new Date(post.created_at).toLocaleDateString('zh-CN')}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex max-h-[calc(90vh-140px)]">
          {/* 左侧图片 - 全图显示 */}
          <div className="w-1/2 bg-gray-100 flex items-center justify-center relative overflow-hidden">
            {post.images.length > 0 ? (
              <div className="w-full h-full relative">
                {/* 主图片显示 */}
                <div className="w-full h-full flex items-center justify-center">
                  <img
                    src={post.images[currentImageIndex]}
                    alt={`图片 ${currentImageIndex + 1}`}
                    className="max-w-full max-h-full object-contain rounded-xl cursor-pointer"
                    style={{ maxWidth: '100%', maxHeight: '100%' }}
                    onClick={() => {
                      // 点击主图片可以切换到下一一张
                      if (post.images.length > 1) {
                        setCurrentImageIndex((prev) => (prev + 1) % post.images.length)
                      }
                    }}
                  />
                </div>
                
                {/* 图片标题（如果有的话） */}
                {post.title && (
                  <div className="absolute top-4 left-4 right-4 bg-black bg-opacity-50 text-white p-3 rounded-lg backdrop-blur-sm">
                    <h2 className="text-lg font-bold mb-1">{post.title}</h2>
                    {post.subtitle && (
                      <p className="text-sm opacity-90">{post.subtitle}</p>
                    )}
                  </div>
                )}
                
                {/* 图片指示器（多图时显示） */}
                {post.images.length > 1 && (
                  <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex space-x-2">
                    {post.images.map((_, index) => (
                      <div
                        key={index}
                        className={`w-2 h-2 rounded-full transition-all ${
                          index === currentImageIndex ? 'bg-white' : 'bg-white bg-opacity-50'
                        }`}
                      />
                    ))}
                  </div>
                )}
                
                {/* 缩略图导航（底部） */}
                {post.images.length > 1 && (
                  <div className="absolute bottom-16 left-4 right-4 flex space-x-2 overflow-x-auto">
                    {post.images.map((image, index) => (
                      <div
                        key={index}
                        className={`flex-shrink-0 w-12 h-12 rounded-lg overflow-hidden border-2 cursor-pointer transition-all ${
                          index === currentImageIndex 
                            ? 'border-white border-opacity-100' 
                            : 'border-white border-opacity-70 hover:border-opacity-100'
                        }`}
                        onClick={() => setCurrentImageIndex(index)}
                      >
                        <img
                          src={image}
                          alt={`缩略图 ${index + 1}`}
                          className="w-full h-full object-cover"
                        />
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center text-gray-400">
                <div className="text-6xl mb-4">🖼️</div>
                <p>暂无图片</p>
              </div>
            )}
          </div>

          {/* 右侧内容 */}
          <div className="w-1/2 flex flex-col">
            {/* 内容区域 */}
            <div className="flex-1 p-6 overflow-y-auto">
              {/* 主标题区域 */}
              {post.title && (
                <div className="mb-4 pb-4 border-b border-gray-200 dark:border-gray-600">
                  <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-200 mb-2">
                    {post.title}
                  </h1>
                  {post.subtitle && (
                    <p className="text-lg text-gray-600 dark:text-gray-400 leading-relaxed">
                      {post.subtitle}
                    </p>
                  )}
                </div>
              )}
              
              {/* 主要内容 */}
              <div className="mb-6">
                <p className="text-gray-800 dark:text-gray-200 text-lg leading-relaxed whitespace-pre-wrap">
                  {post.content}
                </p>
                
                {/* 标签 */}
                {post.tags.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-4">
                    {post.tags.map((tag) => (
                      <span
                        key={tag.id}
                        className="px-3 py-1 bg-gradient-to-r from-pink-100 to-blue-100 text-pink-700 rounded-full text-sm font-medium"
                      >
                        #{tag.name}
                      </span>
                    ))}
                  </div>
                )}
              </div>

              {/* 互动统计 */}
              <div className="flex items-center space-x-6 text-sm text-gray-500 mb-6">
                <span>{likesCount} 个赞</span>
                <span>{comments.length} 条评论</span>
              </div>

              {/* 评论区域 */}
              <CommentSection
                postId={post.id}
                onCommentAdded={handleCommentAdded}
              />
            </div>

            {/* 底部互动按钮 */}
            <div className="border-t p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-6">
                  <button
                    onClick={handleLike}
                    disabled={isLoading}
                    className={`flex items-center space-x-2 transition-colors ${
                      isLiked ? 'text-red-500' : 'text-gray-500 hover:text-red-500'
                    }`}
                  >
                    <Heart className={`w-5 h-5 ${isLiked ? 'fill-current' : ''}`} />
                    <span className="text-sm font-medium">{likesCount}</span>
                  </button>
                  
                  <button className="flex items-center space-x-2 text-gray-500 hover:text-blue-500 transition-colors">
                    <MessageCircle className="w-5 h-5" />
                    <span className="text-sm font-medium">{comments.length}</span>
                  </button>
                  
                  <button
                    onClick={handleFavorite}
                    disabled={isLoading}
                    className={`transition-colors ${
                      isFavorited ? 'text-yellow-500' : 'text-gray-500 hover:text-yellow-500'
                    }`}
                  >
                    <Bookmark className={`w-5 h-5 ${isFavorited ? 'fill-current' : ''}`} />
                  </button>
                </div>
                
                <button className="text-gray-500 hover:text-green-500 transition-colors">
                  <Share2 className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}