/**
 * 图片优化上传工具
 * 提供图片压缩、质量优化和尺寸调整功能
 */

export interface ImageOptimizationOptions {
  maxWidth?: number
  maxHeight?: number
  quality?: number
  maxFileSize?: number
  maintainAspectRatio?: boolean
}

export const DEFAULT_IMAGE_OPTIONS: ImageOptimizationOptions = {
  maxWidth: 1920, // 最大宽度 1920px
  maxHeight: 1080, // 最大高度 1080px
  quality: 0.9, // 高质量 90%
  maxFileSize: 15 * 1024 * 1024, // 最大15MB
  maintainAspectRatio: true
}

// 最高画质选项
export const MAX_QUALITY_IMAGE_OPTIONS: ImageOptimizationOptions = {
  maxWidth: 3840, // 4K 宽度
  maxHeight: 2160, // 4K 高度
  quality: 1.0, // 100% 质量
  maxFileSize: 50 * 1024 * 1024, // 最大50MB
  maintainAspectRatio: true
}

// 原始画质选项（尽可能保持原始）
export const ORIGINAL_QUALITY_IMAGE_OPTIONS: ImageOptimizationOptions = {
  maxWidth: 7680, // 8K 宽度
  maxHeight: 4320, // 8K 高度
  quality: 1.0, // 100% 质量
  maxFileSize: 100 * 1024 * 1024, // 最大100MB
  maintainAspectRatio: true
}

/**
 * 压缩图片
 */
export async function compressImage(
  file: File, 
  options: ImageOptimizationOptions = {}
): Promise<Blob> {
  const opts = { ...DEFAULT_IMAGE_OPTIONS, ...options }
  
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    
    reader.onload = (e) => {
      const img = new Image()
      img.onload = () => {
        try {
          const canvas = document.createElement('canvas')
          const ctx = canvas.getContext('2d')
          
          if (!ctx) {
            reject(new Error('无法创建canvas上下文'))
            return
          }

          // 计算压缩后的尺寸
          let { width, height } = calculateDimensions(
            img.width,
            img.height,
            opts.maxWidth!,
            opts.maxHeight!,
            opts.maintainAspectRatio!
          )

          canvas.width = width
          canvas.height = height

          // 设置高质量图片参数
          ctx.imageSmoothingEnabled = true
          ctx.imageSmoothingQuality = 'high'

          // 绘制图片
          ctx.drawImage(img, 0, 0, width, height)

          // 转换为blob，使用高质量
          canvas.toBlob(
            (blob) => {
              if (blob) {
                resolve(blob)
              } else {
                reject(new Error('图片压缩失败'))
              }
            },
            file.type,
            opts.quality
          )
        } catch (error) {
          reject(error)
        }
      }
      
      img.onerror = () => reject(new Error('图片加载失败'))
      img.src = e.target?.result as string
    }
    
    reader.onerror = () => reject(new Error('文件读取失败'))
    reader.readAsDataURL(file)
  })
}

/**
 * 以最高画质处理图片（最小压缩）
 */
export async function processImageWithMaxQuality(file: File): Promise<Blob> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    
    reader.onload = (e) => {
      const img = new Image()
      img.onload = () => {
        try {
          const canvas = document.createElement('canvas')
          const ctx = canvas.getContext('2d')
          
          if (!ctx) {
            reject(new Error('无法创建canvas上下文'))
            return
          }

          // 使用原始尺寸或4K限制
          let width = img.width
          let height = img.height
          
          // 如果图片超过4K，才进行尺寸调整
          if (width > 3840 || height > 2160) {
            const aspectRatio = width / height
            if (width > height) {
              width = 3840
              height = width / aspectRatio
            } else {
              height = 2160
              width = height * aspectRatio
            }
          }

          canvas.width = width
          canvas.height = height

          // 设置最高质量参数
          ctx.imageSmoothingEnabled = true
          ctx.imageSmoothingQuality = 'high'
          
          // 使用高质量重采样
          ctx.drawImage(img, 0, 0, width, height)

          // 使用100%质量转换为blob
          canvas.toBlob(
            (blob) => {
              if (blob) {
                resolve(blob)
              } else {
                reject(new Error('图片处理失败'))
              }
            },
            file.type,
            1.0 // 100% 质量
          )
        } catch (error) {
          reject(error)
        }
      }
      
      img.onerror = () => reject(new Error('图片加载失败'))
      img.src = e.target?.result as string
    }
    
    reader.onerror = () => reject(new Error('文件读取失败'))
    reader.readAsDataURL(file)
  })
}

/**
 * 以原始画质上传（仅在必要时压缩）
 */
export async function processImageWithOriginalQuality(file: File): Promise<Blob> {
  // 如果文件大小在合理范围内，直接返回原文件
  if (file.size <= 50 * 1024 * 1024) { // 小于50MB
    return Promise.resolve(file)
  }
  
  // 如果文件太大，进行最小压缩
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    
    reader.onload = (e) => {
      const img = new Image()
      img.onload = () => {
        try {
          const canvas = document.createElement('canvas')
          const ctx = canvas.getContext('2d')
          
          if (!ctx) {
            reject(new Error('无法创建canvas上下文'))
            return
          }

          // 使用原始尺寸或8K限制
          let width = img.width
          let height = img.height
          
          // 只在超过8K时才调整尺寸
          if (width > 7680 || height > 4320) {
            const aspectRatio = width / height
            if (width > height) {
              width = 7680
              height = width / aspectRatio
            } else {
              height = 4320
              width = height * aspectRatio
            }
          }

          canvas.width = width
          canvas.height = height

          // 设置最高质量参数
          ctx.imageSmoothingEnabled = true
          ctx.imageSmoothingQuality = 'high'
          
          // 绘制图片
          ctx.drawImage(img, 0, 0, width, height)

          // 使用100%质量转换为blob
          canvas.toBlob(
            (blob) => {
              if (blob) {
                resolve(blob)
              } else {
                reject(new Error('图片处理失败'))
              }
            },
            file.type,
            1.0 // 100% 质量
          )
        } catch (error) {
          reject(error)
        }
      }
      
      img.onerror = () => reject(new Error('图片加载失败'))
      img.src = e.target?.result as string
    }
    
    reader.onerror = () => reject(new Error('文件读取失败'))
    reader.readAsDataURL(file)
  })
}

/**
 * 计算压缩后的尺寸
 */
function calculateDimensions(
  originalWidth: number,
  originalHeight: number,
  maxWidth: number,
  maxHeight: number,
  maintainAspectRatio: boolean
): { width: number; height: number } {
  if (!maintainAspectRatio) {
    return { width: maxWidth, height: maxHeight }
  }

  let width = originalWidth
  let height = originalHeight

  // 如果图片尺寸小于最大限制，不压缩
  if (width <= maxWidth && height <= maxHeight) {
    return { width, height }
  }

  const aspectRatio = width / height

  if (width > maxWidth) {
    width = maxWidth
    height = width / aspectRatio
  }

  if (height > maxHeight) {
    height = maxHeight
    width = height * aspectRatio
  }

  return { width: Math.round(width), height: Math.round(height) }
}

/**
 * 验证文件大小
 */
export function validateFileSize(file: File, maxSize: number): boolean {
  return file.size <= maxSize
}

/**
 * 获取优化的文件名
 * 生成安全的文件名，避免中文字符和特殊字符
 */
export function getOptimizedFileName(originalFile: File, suffix = 'optimized'): string {
  const timestamp = Date.now()
  const extension = originalFile.name.split('.').pop()
  
  // 生成安全的随机字符串，避免中文字符
  const randomStr = Math.random().toString(36).substring(2, 8)
  
  // 根据后缀类型生成对应的标识
  const suffixMap: Record<string, string> = {
    'original': 'orig',
    'high': 'hq',
    'medium': 'std',
    'auto': 'auto',
    'optimized': 'opt'
  }
  
  const safeSuffix = suffixMap[suffix] || suffix
  
  return `${timestamp}-${randomStr}-${safeSuffix}.${extension}`
}

/**
 * 检查图片是否需要压缩
 */
export function shouldCompressImage(file: File, options: ImageOptimizationOptions = {}): Promise<boolean> {
  const opts = { ...DEFAULT_IMAGE_OPTIONS, ...options }
  
  // 如果文件大小超过限制，需要压缩
  if (file.size > opts.maxFileSize!) {
    return Promise.resolve(true)
  }
  
  return new Promise((resolve) => {
    const reader = new FileReader()
    reader.onload = (e) => {
      const img = new Image()
      img.onload = () => {
        // 如果尺寸超过限制，需要压缩
        resolve(img.width > opts.maxWidth! || img.height > opts.maxHeight!)
      }
      img.onerror = () => resolve(false)
      img.src = e.target?.result as string
    }
    reader.onerror = () => resolve(false)
    reader.readAsDataURL(file)
  })
}