import { useState } from 'react'
import { blockUser, unblockUser, isUserBlocked } from '../lib/blocking'
import { toast } from 'sonner'

interface BlockUserButtonProps {
  targetUserId: string
  targetUserName?: string
  size?: 'sm' | 'md' | 'lg'
  variant?: 'button' | 'icon'
  onBlockStatusChange?: (isBlocked: boolean) => void
}

export const BlockUserButton = ({ 
  targetUserId, 
  targetUserName = '此用户',
  size = 'md',
  variant = 'button',
  onBlockStatusChange
}: BlockUserButtonProps) => {
  const [isBlocked, setIsBlocked] = useState(false)
  const [isLoading, setIsLoading] = useState(false)

  const handleBlock = async () => {
    setIsLoading(true)
    try {
      if (isBlocked) {
        await unblockUser(targetUserId)
        setIsBlocked(false)
        toast.success(`已取消拉黑 ${targetUserName}`)
        onBlockStatusChange?.(false)
      } else {
        await blockUser(targetUserId, '用户主动拉黑')
        setIsBlocked(true)
        toast.success(`已拉黑 ${targetUserName}`)
        onBlockStatusChange?.(true)
      }
    } catch (error) {
      toast.error(isBlocked ? '取消拉黑失败' : '拉黑失败')
      console.error('拉黑操作失败:', error)
    } finally {
      setIsLoading(false)
    }
  }

  if (variant === 'icon') {
    return (
      <button
        onClick={handleBlock}
        disabled={isLoading}
        className={`p-2 rounded-full transition-colors ${
          isBlocked 
            ? 'bg-red-100 text-red-600 hover:bg-red-200' 
            : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
        } ${size === 'sm' ? 'text-sm' : size === 'lg' ? 'text-lg' : 'text-base'}`}
        title={isBlocked ? '取消拉黑' : '拉黑用户'}
      >
        {isBlocked ? '🚫' : '⛔'}
      </button>
    )
  }

  return (
    <button
      onClick={handleBlock}
      disabled={isLoading}
      className={`px-4 py-2 rounded-lg font-medium transition-colors ${
        isBlocked
          ? 'bg-red-500 text-white hover:bg-red-600'
          : 'bg-gray-500 text-white hover:bg-gray-600'
      } ${size === 'sm' ? 'text-sm px-3 py-1' : size === 'lg' ? 'text-lg px-6 py-3' : ''} ${
        isLoading ? 'opacity-50 cursor-not-allowed' : ''
      }`}
    >
      {isLoading ? (
        '处理中...'
      ) : isBlocked ? (
        '已拉黑'
      ) : (
        '拉黑用户'
      )}
    </button>
  )
}