import { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'

export interface BlockedTag {
  id: string
  tag_id: string
  tag_name: string
  blocked_at: string
  reason?: string
}

export interface BlockedUser {
  id: string
  blocked_user_id: string
  blocked_username: string
  blocked_at: string
  reason?: string
}

export function useBlockedTags() {
  const [blockedTags, setBlockedTags] = useState<BlockedTag[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const { user } = useAuth()

  const fetchBlockedTags = async () => {
    if (!user) {
      setBlockedTags([])
      setIsLoading(false)
      return
    }

    try {
      setIsLoading(true)
      
      // 简化查询，避免复杂的关系查询
      const { data, error } = await supabase
        .from('user_blocked_tags')
        .select('id, tag_id, blocked_at, reason')
        .eq('user_id', user.id)
        .order('blocked_at', { ascending: false })

      if (error) {
        console.warn('获取屏蔽标签失败:', error)
        // 如果是权限错误，返回空数组而不是抛出错误
        if (error.code === 'PGRST116' || error.code === '42501') {
          setBlockedTags([])
          setIsLoading(false)
          return
        }
        setBlockedTags([])
        return
      }

      // 获取标签名称
      if (data && data.length > 0) {
        const tagIds = data.map(item => item.tag_id)
        const { data: tagData, error: tagError } = await supabase
          .from('tags')
          .select('id, name')
          .in('id', tagIds)

        if (tagError) {
          console.warn('获取标签信息失败:', tagError)
        }

        const tagMap = new Map()
        if (tagData) {
          tagData.forEach(tag => tagMap.set(tag.id, tag.name))
        }

        const tags: BlockedTag[] = data.map((item: any) => ({
          id: item.id,
          tag_id: item.tag_id,
          tag_name: tagMap.get(item.tag_id) || '未知标签',
          blocked_at: item.blocked_at,
          reason: item.reason
        }))

        setBlockedTags(tags)
      } else {
        setBlockedTags([])
      }
    } catch (error) {
      console.error('获取屏蔽标签失败:', error)
      setBlockedTags([])
    } finally {
      setIsLoading(false)
    }
  }

  const blockTag = async (tagId: string, reason?: string) => {
    if (!user) {
      throw new Error('用户未登录')
    }

    try {
      const { error } = await supabase
        .from('user_blocked_tags')
        .insert({
          user_id: user.id,
          tag_id: tagId,
          reason
        })

      if (error) throw error

      await fetchBlockedTags()
    } catch (error) {
      console.error('屏蔽标签失败:', error)
      throw error
    }
  }

  const unblockTag = async (tagId: string) => {
    if (!user) {
      throw new Error('用户未登录')
    }

    try {
      const { error } = await supabase
        .from('user_blocked_tags')
        .delete()
        .eq('user_id', user.id)
        .eq('tag_id', tagId)

      if (error) throw error

      await fetchBlockedTags()
    } catch (error) {
      console.error('取消屏蔽标签失败:', error)
      throw error
    }
  }

  const isTagBlocked = (tagId: string): boolean => {
    return blockedTags.some(tag => tag.tag_id === tagId)
  }

  const getBlockedTagIds = (): string[] => {
    return blockedTags.map(tag => tag.tag_id)
  }

  useEffect(() => {
    fetchBlockedTags()
  }, [user])

  return {
    blockedTags,
    isLoading,
    blockTag,
    unblockTag,
    isTagBlocked,
    getBlockedTagIds,
    refetch: fetchBlockedTags
  }
}

export function useBlockedUsers() {
  const [blockedUsers, setBlockedUsers] = useState<BlockedUser[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const { user } = useAuth()

  const fetchBlockedUsers = async () => {
    if (!user) {
      setBlockedUsers([])
      setIsLoading(false)
      return
    }

    try {
      setIsLoading(true)
      
      // 简化查询，避免复杂的关系查询
      const { data, error } = await supabase
        .from('user_blocked_users')
        .select('id, blocked_user_id, blocked_at, reason')
        .eq('user_id', user.id)
        .order('blocked_at', { ascending: false })

      if (error) {
        console.warn('获取拉黑用户失败:', error)
        // 如果是权限错误，返回空数组而不是抛出错误
        if (error.code === 'PGRST116' || error.code === '42501') {
          setBlockedUsers([])
          setIsLoading(false)
          return
        }
        setBlockedUsers([])
        return
      }

      // 获取被拉黑用户的信息
      if (data && data.length > 0) {
        const userIds = data.map(item => item.blocked_user_id)
        const { data: userData, error: userError } = await supabase
          .from('users')
          .select('id, username')
          .in('id', userIds)

        if (userError) {
          console.warn('获取用户信息失败:', userError)
        }

        const userMap = new Map()
        if (userData) {
          userData.forEach(user => userMap.set(user.id, user.username))
        }

        const users: BlockedUser[] = data.map((item: any) => ({
          id: item.id,
          blocked_user_id: item.blocked_user_id,
          blocked_username: userMap.get(item.blocked_user_id) || '未知用户',
          blocked_at: item.blocked_at,
          reason: item.reason
        }))

        setBlockedUsers(users)
      } else {
        setBlockedUsers([])
      }
    } catch (error) {
      console.error('获取拉黑用户失败:', error)
      setBlockedUsers([])
    } finally {
      setIsLoading(false)
    }
  }

  const blockUser = async (blockedUserId: string, reason?: string) => {
    if (!user) {
      throw new Error('用户未登录')
    }

    if (user.id === blockedUserId) {
      throw new Error('不能拉黑自己')
    }

    try {
      const { error } = await supabase
        .from('user_blocked_users')
        .insert({
          user_id: user.id,
          blocked_user_id: blockedUserId,
          reason
        })

      if (error) throw error

      await fetchBlockedUsers()
    } catch (error) {
      console.error('拉黑用户失败:', error)
      throw error
    }
  }

  const unblockUser = async (blockedUserId: string) => {
    if (!user) {
      throw new Error('用户未登录')
    }

    try {
      const { error } = await supabase
        .from('user_blocked_users')
        .delete()
        .eq('user_id', user.id)
        .eq('blocked_user_id', blockedUserId)

      if (error) throw error

      await fetchBlockedUsers()
    } catch (error) {
      console.error('取消拉黑用户失败:', error)
      throw error
    }
  }

  const isUserBlocked = (userId: string): boolean => {
    return blockedUsers.some(user => user.blocked_user_id === userId)
  }

  const getBlockedUserIds = (): string[] => {
    return blockedUsers.map(user => user.blocked_user_id)
  }

  useEffect(() => {
    fetchBlockedUsers()
  }, [user])

  return {
    blockedUsers,
    isLoading,
    blockUser,
    unblockUser,
    isUserBlocked,
    getBlockedUserIds,
    refetch: fetchBlockedUsers
  }
}