/**
 * 图片上传质量选择器
 * 允许用户选择上传图片的质量模式
 */

import { useState } from 'react'
import { Settings, Image, Camera, Maximize } from 'lucide-react'

export type UploadQuality = 'original' | 'high' | 'medium' | 'auto'

interface QualitySelectorProps {
  quality: UploadQuality
  onQualityChange: (quality: UploadQuality) => void
  disabled?: boolean
}

const qualityOptions = [
  {
    value: 'original' as UploadQuality,
    label: '原始画质',
    description: '尽可能保持原始质量，文件较大',
    icon: Maximize,
    color: 'text-green-600 dark:text-green-400',
    bgColor: 'bg-green-50 dark:bg-green-900/20',
    borderColor: 'border-green-200 dark:border-green-700'
  },
  {
    value: 'high' as UploadQuality,
    label: '高清画质',
    description: '高质量压缩，平衡画质和大小',
    icon: Camera,
    color: 'text-blue-600 dark:text-blue-400',
    bgColor: 'bg-blue-50 dark:bg-blue-900/20',
    borderColor: 'border-blue-200 dark:border-blue-700'
  },
  {
    value: 'medium' as UploadQuality,
    label: '标准画质',
    description: '标准压缩，适合日常使用',
    icon: Image,
    color: 'text-purple-600 dark:text-purple-400',
    bgColor: 'bg-purple-50 dark:bg-purple-900/20',
    borderColor: 'border-purple-200 dark:border-purple-700'
  },
  {
    value: 'auto' as UploadQuality,
    label: '智能优化',
    description: '自动选择最佳质量方案',
    icon: Settings,
    color: 'text-pink-600 dark:text-pink-400',
    bgColor: 'bg-pink-50 dark:bg-pink-900/20',
    borderColor: 'border-pink-200 dark:border-pink-700'
  }
]

export function QualitySelector({ quality, onQualityChange, disabled = false }: QualitySelectorProps) {
  const [isOpen, setIsOpen] = useState(false)

  const selectedOption = qualityOptions.find(option => option.value === quality) || qualityOptions[1]
  const SelectedIcon = selectedOption.icon

  return (
    <div className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        disabled={disabled}
        className={`flex items-center space-x-2 px-3 py-2 rounded-lg border transition-all duration-200 ${
          selectedOption.bgColor
        } ${selectedOption.borderColor} ${selectedOption.color} hover:opacity-80 disabled:opacity-50 disabled:cursor-not-allowed`}
      >
        <SelectedIcon className="w-4 h-4" />
        <span className="text-sm font-medium">{selectedOption.label}</span>
        <svg
          className={`w-4 h-4 transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`}
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-600 p-2 z-10">
          {qualityOptions.map((option) => {
            const Icon = option.icon
            return (
              <button
                key={option.value}
                onClick={() => {
                  onQualityChange(option.value)
                  setIsOpen(false)
                }}
                className={`w-full flex items-center space-x-3 p-3 rounded-lg mb-1 last:mb-0 transition-all duration-200 ${
                  quality === option.value
                    ? `${option.bgColor} ${option.borderColor} border`
                    : 'hover:bg-gray-50 dark:hover:bg-gray-700'
                }`}
              >
                <Icon className={`w-5 h-5 ${option.color}`} />
                <div className="flex-1 text-left">
                  <div className={`text-sm font-medium ${option.color}`}>
                    {option.label}
                  </div>
                  <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                    {option.description}
                  </div>
                </div>
                {quality === option.value && (
                  <div className={`w-2 h-2 rounded-full ${option.color.replace('text-', 'bg-')}`} />
                )}
              </button>
            )
          })}
        </div>
      )}
    </div>
  )
}

/**
 * 获取对应的质量处理函数
 */
export function getQualityProcessor(quality: UploadQuality) {
  switch (quality) {
    case 'original':
      return import('../utils/imageOptimization').then(module => module.processImageWithOriginalQuality)
    case 'high':
      return import('../utils/imageOptimization').then(module => module.processImageWithMaxQuality)
    case 'medium':
      return import('../utils/imageOptimization').then(module => module.compressImage)
    case 'auto':
    default:
      return import('../utils/imageOptimization').then(module => module.processImageWithMaxQuality)
  }
}