import { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuthStore } from '../stores/authStore'
import { useBlockedTags, useBlockedUsers } from './useBlocking'

export interface FollowedTag {
  id: string
  name: string
  usage_count: number
  followers_count: number
  category?: string
  followed_at: string
}

export function useFollowedTags() {
  const [followedTags, setFollowedTags] = useState<FollowedTag[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const { user } = useAuthStore()

  const fetchFollowedTags = async () => {
    if (!user) {
      setFollowedTags([])
      setIsLoading(false)
      return
    }

    try {
      setIsLoading(true)
      
      // 获取用户关注的标签
      const { data, error } = await supabase
        .from('user_tags')
        .select(`
          created_at,
          tag:tags(id, name, usage_count, followers_count, category)
        `)
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })

      if (error) throw error

      const tags: FollowedTag[] = (data || []).map((item: any) => ({
        id: item.tag.id,
        name: item.tag.name,
        usage_count: item.tag.usage_count,
        followers_count: item.tag.followers_count,
        category: item.tag.category,
        followed_at: item.created_at
      }))

      setFollowedTags(tags)
    } catch (error) {
      console.error('获取关注的标签失败:', error)
      setFollowedTags([])
    } finally {
      setIsLoading(false)
    }
  }

  const followTag = async (tagId: string) => {
    if (!user) {
      throw new Error('用户未登录')
    }

    try {
      const { error } = await supabase
        .from('user_tags')
        .insert({
          user_id: user.id,
          tag_id: tagId
        })

      if (error) throw error

      // 重新获取关注的标签
      await fetchFollowedTags()
    } catch (error) {
      console.error('关注标签失败:', error)
      throw error
    }
  }

  const unfollowTag = async (tagId: string) => {
    if (!user) {
      throw new Error('用户未登录')
    }

    try {
      const { error } = await supabase
        .from('user_tags')
        .delete()
        .eq('user_id', user.id)
        .eq('tag_id', tagId)

      if (error) throw error

      // 重新获取关注的标签
      await fetchFollowedTags()
    } catch (error) {
      console.error('取消关注标签失败:', error)
      throw error
    }
  }

  const isFollowingTag = (tagId: string): boolean => {
    return followedTags.some(tag => tag.id === tagId)
  }

  useEffect(() => {
    fetchFollowedTags()
  }, [user])

  return {
    followedTags,
    isLoading,
    followTag,
    unfollowTag,
    isFollowingTag,
    refetch: fetchFollowedTags
  }
}

export function useFollowedTagsPosts(limit = 20) {
  const [posts, setPosts] = useState<any[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const { user } = useAuthStore()
  const { followedTags } = useFollowedTags()
  const { getBlockedTagIds } = useBlockedTags()
  const { getBlockedUserIds } = useBlockedUsers()

  const fetchFollowedTagsPosts = async () => {
    if (!user || followedTags.length === 0) {
      setPosts([])
      setIsLoading(false)
      return
    }

    try {
      setIsLoading(true)
      
      // 获取屏蔽的标签和用户ID
      const blockedTagIds = getBlockedTagIds()
      const blockedUserIds = getBlockedUserIds()

      // 获取关注标签的ID（排除已屏蔽的标签）
      const tagIds = followedTags
        .filter(tag => !blockedTagIds.includes(tag.id))
        .map(tag => tag.id)
      
      if (tagIds.length === 0) {
        setPosts([])
        setIsLoading(false)
        return
      }
      
      // 获取这些标签关联的帖子
      const { data: postTagData, error: postTagError } = await supabase
        .from('post_tags')
        .select('post_id')
        .in('tag_id', tagIds)

      if (postTagError) throw postTagError

      const postIds = (postTagData || []).map(item => item.post_id)
      
      if (postIds.length === 0) {
        setPosts([])
        setIsLoading(false)
        return
      }

      // 获取帖子详细信息（排除屏蔽的用户）
      let postsQuery = supabase
        .from('posts')
        .select(`
          *,
          user:users(id, username, avatar_url, display_name),
          tags:post_tags(tag:tags(id, name, category))
        `)
        .in('id', postIds)
        .order('created_at', { ascending: false })
        .limit(limit)

      // 如果有屏蔽的用户，排除这些用户的帖子
      if (blockedUserIds.length > 0) {
        postsQuery = postsQuery.not('user_id', 'in', `(${blockedUserIds.join(',')})`)
      }

      const { data: postsData, error: postsError } = await postsQuery

      if (postsError) throw postsError

      // 获取点赞状态
      const { data: likesData } = await supabase
        .from('likes')
        .select('post_id')
        .eq('user_id', user.id)
        .in('post_id', postIds)

      const likedPostIds = new Set((likesData || []).map(like => like.post_id))

      const postsWithLikeStatus = (postsData || []).map(post => ({
        ...post,
        is_liked: likedPostIds.has(post.id),
        images: Array.isArray(post.images) ? post.images : [],
        videos: Array.isArray(post.videos) ? post.videos : [],
        user: post.user || { id: post.user_id, username: '未知用户', avatar_url: null }
      }))

      setPosts(postsWithLikeStatus)
    } catch (error) {
      console.error('获取关注标签的帖子失败:', error)
      setPosts([])
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchFollowedTagsPosts()
  }, [followedTags, user])

  return {
    posts,
    isLoading,
    refetch: fetchFollowedTagsPosts
  }
}