import { useState, useRef } from 'react'
import { supabase, supabaseConfig } from '../lib/supabase'
import { toast } from 'sonner'
import { X, Upload, Hash } from 'lucide-react'
import { compressImage, getOptimizedFileName, validateFileSize, processImageWithMaxQuality } from '../utils/imageOptimization'
import { QualitySelector, UploadQuality, getQualityProcessor } from './QualitySelector'

interface CreatePostModalProps {
  isOpen: boolean
  onClose: () => void
  onSuccess?: () => void
}

export function CreatePostModal({ isOpen, onClose, onSuccess }: CreatePostModalProps) {
  const [title, setTitle] = useState('')
  const [subtitle, setSubtitle] = useState('')
  const [content, setContent] = useState('')
  const [images, setImages] = useState<string[]>([])
  const [tags, setTags] = useState<string[]>([])
  const [newTag, setNewTag] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [uploadProgress, setUploadProgress] = useState<Record<string, number>>({})
  const [uploadQuality, setUploadQuality] = useState<UploadQuality>('high')
  const fileInputRef = useRef<HTMLInputElement>(null)

  if (!isOpen) return null

  const handleMediaUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files
    if (!files) return

    setIsLoading(true)
    
    try {
      // 获取当前用户信息
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        throw new Error('请先登录后再上传图片')
      }

      const uploadPromises = Array.from(files).map(async (file) => {
        // 验证文件类型 - 只支持图片
        const allowedImageTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif']
        
        if (!allowedImageTypes.includes(file.type)) {
          throw new Error(`不支持的文件类型: ${file.type}。目前只支持图片格式。`)
        }

        // 验证文件大小 - 增加到50MB用于最高画质图片
        const maxImageSize = 50 * 1024 * 1024 // 50MB for maximum quality images
        
        if (!validateFileSize(file, maxImageSize)) {
          throw new Error(`图片大小不能超过 ${maxImageSize / (1024 * 1024)}MB`)
        }

        // 根据选择的质量模式处理图片
        let processedFile: File | Blob = file
        let shouldShowProcessingNotice = false
        
        try {
          // 获取对应的质量处理函数
          const qualityProcessor = await getQualityProcessor(uploadQuality)
          const processedBlob = await qualityProcessor(file)
          
          if (processedBlob.size !== file.size) {
            processedFile = new File([processedBlob], file.name, { type: file.type })
            shouldShowProcessingNotice = true
            console.log(`图片已按${uploadQuality}模式处理: ${file.size} -> ${processedBlob.size} bytes`)
          }
        } catch (processingError) {
          console.warn('图片处理失败，使用原文件:', processingError)
          processedFile = file
        }

        const fileName = getOptimizedFileName(file, uploadQuality)
        // 根据Supabase存储策略，文件路径需要以用户ID开头
        const filePath = `${user.id}/${fileName}`
        
        // 上传文件
        console.log('开始上传优化后的文件:', fileName, '到存储桶: posts', '路径:', filePath)
        const { error: uploadError } = await supabase.storage
          .from('posts')
          .upload(filePath, processedFile, {
            cacheControl: '2592000', // 30天缓存
            upsert: false,
            contentType: file.type
          })

        if (shouldShowProcessingNotice) {
          const qualityLabels = {
            original: '原始画质',
            high: '高清画质',
            medium: '标准画质',
            auto: '智能优化'
          }
          toast.success(`✨ 图片以${qualityLabels[uploadQuality]}处理完成`)
        }

        if (uploadError) {
          console.error('上传错误详情:', uploadError)
          console.error('错误消息:', uploadError.message)
          
          if (uploadError.message.includes('bucket')) {
            throw new Error('存储桶配置错误，请联系管理员')
          } else if (uploadError.message.includes('permission')) {
            throw new Error('权限不足，无法上传文件')
          } else if (uploadError.message.includes('Row Level Security')) {
            throw new Error('安全策略阻止上传，请联系管理员')
          } else {
            throw new Error(`文件上传失败: ${uploadError.message}`)
          }
        }

        // 获取公共URL
        const { data: urlData } = supabase.storage
          .from('posts')
          .getPublicUrl(filePath)

        if (!urlData?.publicUrl) {
          throw new Error('无法获取文件URL')
        }

        return { url: urlData.publicUrl, type: file.type }
      })

      const uploadedMedia = await Promise.all(uploadPromises)
      
      // 只处理图片
      const imageUrls = uploadedMedia.map(media => media.url)
      
      if (imageUrls.length > 0) {
        setImages(prev => [...prev, ...imageUrls])
        toast.success(`成功上传 ${imageUrls.length} 张图片`)
      }
    } catch (error) {
      console.error('上传失败:', error)
      const errorMessage = error instanceof Error ? error.message : '文件上传失败，请重试'
      toast.error(errorMessage)
    } finally {
      setIsLoading(false)
      // 清空input值，允许重复选择同一文件
      event.target.value = ''
    }
  }

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index))
  }

  const addTag = () => {
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags(prev => [...prev, newTag.trim()])
      setNewTag('')
    }
  }

  const removeTag = (tagToRemove: string) => {
    setTags(prev => prev.filter(tag => tag !== tagToRemove))
  }

  const handleSubmit = async () => {
    if (!title.trim() && !subtitle.trim() && !content.trim() && images.length === 0) {
      toast.error('请输入标题、内容或上传图片')
      return
    }

    setIsLoading(true)

    try {
      // 检查用户登录状态
      const { data: { user }, error: authError } = await supabase.auth.getUser()
      
      if (authError || !user) {
        console.error('用户认证错误:', authError)
        toast.error('请先登录后再发布帖子')
        setIsLoading(false)
        return
      }

      console.log('当前用户ID:', user.id)
      console.log('主标题:', title.trim())
      console.log('副标题:', subtitle.trim())
      console.log('发布内容:', content.trim())
      console.log('图片数量:', images.length)

      // 创建帖子数据
      const postData = {
        user_id: user.id,
        title: title.trim() || null,
        subtitle: subtitle.trim() || null,
        content: content.trim() || null,
        images: images.length > 0 ? images : []
      }

      console.log('准备插入的帖子数据:', postData)

      // 创建帖子
      const { data: post, error: postError } = await supabase
        .from('posts')
        .insert(postData)
        .select()
        .single()

      if (postError) {
        console.error('创建帖子失败:', postError)
        console.error('错误详情:', JSON.stringify(postError, null, 2))
        throw new Error(`创建帖子失败: ${postError.message}`)
      }

      // 处理标签（简化版本，避免权限问题）
      if (tags.length > 0) {
        try {
          for (const tagName of tags) {
            // 检查标签是否存在
            const { data: existingTag, error: checkError } = await supabase
              .from('tags')
              .select('id')
              .eq('name', tagName)
              .single()

            let tagId
            if (existingTag) {
              tagId = existingTag.id
            } else {
              // 创建新标签
              const { data: newTag, error: createError } = await supabase
                .from('tags')
                .insert({ name: tagName })
                .select()
                .single()
              
              if (createError) {
                console.warn(`创建标签 ${tagName} 失败:`, createError)
                continue // 跳过失败的标签
              }
              tagId = newTag?.id
            }

            if (tagId) {
              // 关联帖子和标签
              const { error: linkError } = await supabase
                .from('post_tags')
                .insert({
                  post_id: post.id,
                  tag_id: tagId
                })
              
              if (linkError) {
                console.warn(`关联标签 ${tagName} 失败:`, linkError)
              }
            }
          }
        } catch (tagError) {
          console.warn('处理标签时出错:', tagError)
          // 标签处理失败不影响帖子创建
        }
      }

      toast.success('发布成功！')
      onSuccess?.()
      onClose()
      
      // 重置表单
      setTitle('')
      setSubtitle('')
      setContent('')
      setImages([])
      setTags([])
    } catch (error) {
      console.error('发布帖子失败:', error)
      let errorMessage = '发布失败'
      
      if (error instanceof Error) {
        errorMessage = error.message
        if (errorMessage.includes('violates')) {
          errorMessage = '数据验证失败，请检查输入内容'
        } else if (errorMessage.includes('permission')) {
          errorMessage = '权限不足，无法发布帖子'
        } else if (errorMessage.includes('Row Level Security')) {
          errorMessage = '安全策略阻止发布，请联系管理员'
        } else if (errorMessage.includes('未登录')) {
          errorMessage = '请先登录后再发布'
        }
      }
      
      toast.error(errorMessage)
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-2 sm:p-4">
      <div className="bg-white dark:bg-gray-900 rounded-2xl sm:rounded-3xl shadow-2xl w-full max-w-2xl max-h-[95vh] sm:max-h-[90vh] overflow-hidden border border-gray-200 dark:border-gray-700">
        {/* 头部 */}
        <div className="flex items-center justify-between p-4 sm:p-6 border-b border-gray-200 dark:border-gray-700">
          <h2 className="text-lg sm:text-xl font-semibold text-gray-800 dark:text-gray-100">发布新帖子</h2>
          <button
            onClick={onClose}
            className="text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 transition-colors p-1"
          >
            <X className="w-5 h-5 sm:w-6 sm:h-6" />
          </button>
        </div>

        {/* 内容区域 */}
        <div className="p-4 sm:p-6 overflow-y-auto max-h-[calc(95vh-180px)] sm:max-h-[calc(90vh-200px)] bg-gray-50 dark:bg-gray-800/50">
          {/* 主标题输入 */}
          <div className="mb-3 sm:mb-4">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200 mb-1 sm:mb-2">
              主标题（可选）
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-3 sm:px-4 py-2 sm:py-3 border border-gray-300 dark:border-gray-600 rounded-lg sm:rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-transparent bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 text-sm sm:text-base"
              placeholder="给你的帖子起个标题..."
              maxLength={100}
            />
          </div>

          {/* 副标题输入 */}
          <div className="mb-3 sm:mb-4">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200 mb-1 sm:mb-2">
              副标题（可选）
            </label>
            <input
              type="text"
              value={subtitle}
              onChange={(e) => setSubtitle(e.target.value)}
              className="w-full px-3 sm:px-4 py-2 sm:py-3 border border-gray-300 dark:border-gray-600 rounded-lg sm:rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-transparent bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 text-sm sm:text-base"
              placeholder="简短描述一下..."
              maxLength={200}
            />
          </div>

          {/* 主要内容输入 */}
          <div className="mb-4 sm:mb-6">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200 mb-1 sm:mb-2">
              分享你的想法
            </label>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full px-3 sm:px-4 py-2 sm:py-3 border border-gray-300 dark:border-gray-600 rounded-lg sm:rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-transparent resize-none bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 text-sm sm:text-base"
              rows={3}
              placeholder="今天有什么想分享的吗？"
            />
          </div>

          {/* 媒体上传 */}
          <div className="mb-4 sm:mb-6">
            <div className="flex items-center justify-between mb-2">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-200">
                添加图片
              </label>
              <QualitySelector
                quality={uploadQuality}
                onQualityChange={setUploadQuality}
                disabled={isLoading}
              />
            </div>
            <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
              {/* 图片预览 */}
              {images.map((image, index) => (
                <div key={`img-${index}`} className="relative aspect-square rounded-lg sm:rounded-xl overflow-hidden border border-gray-200 dark:border-gray-600">
                  <img
                    src={image}
                    alt={`图片 ${index + 1}`}
                    className="w-full h-full object-cover"
                  />
                  <button
                    onClick={() => removeImage(index)}
                    className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 hover:bg-red-600 transition-colors shadow-lg"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </div>
              ))}
              

              {images.length < 9 && (
                <label className="aspect-square border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg sm:rounded-xl flex items-center justify-center cursor-pointer hover:border-pink-500 dark:hover:border-pink-400 transition-colors bg-gray-50 dark:bg-gray-700/50">
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/*"
                    multiple
                    onChange={handleMediaUpload}
                    className="hidden"
                  />
                  <Upload className="w-6 h-6 sm:w-8 sm:h-8 text-gray-400 dark:text-gray-500" />
                </label>
              )}
            </div>
          </div>

          {/* 标签输入 */}
          <div className="mb-4 sm:mb-6">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200 mb-1 sm:mb-2">
              添加标签
            </label>
            <div className="flex items-center space-x-2 mb-2">
              <Hash className="w-4 h-4 sm:w-5 sm:h-5 text-gray-400 dark:text-gray-500" />
              <input
                type="text"
                value={newTag}
                onChange={(e) => setNewTag(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && addTag()}
                className="flex-1 px-3 sm:px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg sm:rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-transparent bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 text-sm sm:text-base"
                placeholder="输入标签名称"
              />
              <button
                onClick={addTag}
                className="px-3 sm:px-4 py-2 bg-gradient-to-r from-pink-500 to-blue-500 text-white rounded-lg sm:rounded-xl font-medium hover:from-pink-600 hover:to-blue-600 transition-all duration-200 text-sm sm:text-base"
              >
                添加
              </button>
            </div>
            
            <div className="flex flex-wrap gap-1 sm:gap-2">
              {tags.map((tag) => (
                <span
                  key={tag}
                  className="px-2 sm:px-3 py-1 bg-gradient-to-r from-pink-100 to-blue-100 dark:from-pink-900/30 dark:to-blue-900/30 text-pink-700 dark:text-pink-300 rounded-full text-xs sm:text-sm font-medium flex items-center space-x-1 border border-pink-200 dark:border-pink-800"
                >
                  <span>#{tag}</span>
                  <button
                    onClick={() => removeTag(tag)}
                    className="text-pink-500 dark:text-pink-400 hover:text-pink-700 dark:hover:text-pink-200"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              ))}
            </div>
          </div>
        </div>

        {/* 底部按钮 */}
        <div className="flex items-center justify-end space-x-3 sm:space-x-4 p-4 sm:p-6 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
          <button
            onClick={onClose}
            className="px-4 sm:px-6 py-2 text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200 transition-colors text-sm sm:text-base"
          >
            取消
          </button>
          <button
            onClick={handleSubmit}
            disabled={isLoading || (!content.trim() && images.length === 0)}
            className="px-6 sm:px-8 py-2 bg-gradient-to-r from-pink-500 to-blue-500 text-white rounded-lg sm:rounded-xl font-semibold hover:from-pink-600 hover:to-blue-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 text-sm sm:text-base shadow-lg"
          >
            {isLoading ? '发布中...' : '发布'}
          </button>
        </div>
      </div>
    </div>
  )
}