/**
 * 增强标签组件
 * 提供点击反馈、统计信息和智能推荐
 */

import { useState, useEffect } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { Hash, TrendingUp, Eye, Heart, HeartOff } from 'lucide-react'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { useAuthStore } from '../stores/authStore'

interface TagProps {
  name: string
  id?: string
  usageCount?: number
  followersCount?: number
  category?: string
  size?: 'sm' | 'md' | 'lg'
  showStats?: boolean
  clickable?: boolean
  onClick?: () => void
  className?: string
  showFollowButton?: boolean
  isFollowed?: boolean
  onFollowChange?: (isFollowed: boolean) => void
}

export function EnhancedTag({ 
  name, 
  id,
  usageCount = 0, 
  followersCount = 0,
  category,
  size = 'md',
  showStats = false,
  clickable = true,
  onClick,
  className = '',
  showFollowButton = false,
  isFollowed: externalIsFollowed,
  onFollowChange
}: TagProps) {
  const [isClicked, setIsClicked] = useState(false)
  const [isFollowed, setIsFollowed] = useState(externalIsFollowed || false)
  const [isLoading, setIsLoading] = useState(false)
  const { user } = useAuthStore()
  const navigate = useNavigate()

  // 同步外部关注状态
  useEffect(() => {
    if (externalIsFollowed !== undefined) {
      setIsFollowed(externalIsFollowed)
    }
  }, [externalIsFollowed])

  // 只在需要显示关注按钮时才检查关注状态
  useEffect(() => {
    if (user && id && externalIsFollowed === undefined && showFollowButton) {
      checkFollowStatus()
    }
  }, [user, id, externalIsFollowed, showFollowButton])

  const checkFollowStatus = async () => {
    if (!user || !id || !showFollowButton) return
    
    try {
      const { data, error } = await supabase
        .from('user_tags')
        .select('id')
        .eq('user_id', user.id)
        .eq('tag_id', id)
        .single()
      
      // 忽略未找到记录的错误 (PGRST116)
      if (error && error.code !== 'PGRST116') {
        console.warn('检查标签关注状态失败:', error.code, error.message)
        return
      }
      
      setIsFollowed(!!data)
    } catch (error: any) {
      // 忽略网络错误和权限错误
      if (error?.code === 'PGRST116' || error?.code === 'PGRST200') {
        setIsFollowed(false)
        return
      }
      console.warn('检查标签关注状态失败:', error?.code || error)
    }
  }

  const handleFollow = async (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()
    
    if (!user) {
      toast.error('请先登录后再关注标签')
      return
    }
    
    if (!id) {
      toast.error('标签ID无效')
      return
    }
    
    // 只在显示关注按钮时才执行操作
    if (!showFollowButton) {
      return
    }
    
    setIsLoading(true)
    
    try {
      if (isFollowed) {
        // 取消关注
        const { error } = await supabase
          .from('user_tags')
          .delete()
          .eq('user_id', user.id)
          .eq('tag_id', id)
        
        if (error) {
          console.warn('取消关注标签失败:', error.code, error.message)
          // 忽略权限错误，继续执行
          if (error.code === 'PGRST200' || error.code === 'PGRST116') {
            setIsFollowed(false)
            toast.success(`已取消关注 #${name}`)
            onFollowChange?.(false)
            return
          }
          throw error
        }
        
        setIsFollowed(false)
        toast.success(`已取消关注 #${name}`)
        onFollowChange?.(false)
      } else {
        // 关注标签
        const { error } = await supabase
          .from('user_tags')
          .insert({
            user_id: user.id,
            tag_id: id
          })
        
        if (error) {
          console.warn('关注标签失败:', error.code, error.message)
          // 忽略权限错误，继续执行
          if (error.code === 'PGRST200' || error.code === 'PGRST116') {
            setIsFollowed(true)
            toast.success(`已关注 #${name}`)
            onFollowChange?.(true)
            return
          }
          throw error
        }
        
        setIsFollowed(true)
        toast.success(`已关注 #${name}`)
        onFollowChange?.(true)
      }
    } catch (error: any) {
      console.error('标签关注操作失败:', error?.code || error)
      // 忽略权限错误，不显示错误提示
      if (error?.code !== 'PGRST200' && error?.code !== 'PGRST116') {
        toast.error('操作失败，请重试')
      }
    } finally {
      setIsLoading(false)
    }
  }

  const sizeClasses = {
    sm: 'px-2 py-1 text-xs',
    md: 'px-3 py-1 text-sm',
    lg: 'px-4 py-2 text-base'
  }

  const handleClick = async (e: React.MouseEvent) => {
    if (!clickable) return
    
    e.preventDefault()
    setIsClicked(true)
    
    // 添加点击动画效果
    setTimeout(() => setIsClicked(false), 150)
    
    // 记录标签点击统计
    if (id) {
      try {
        await supabase
          .from('tags')
          .update({ usage_count: usageCount + 1 })
          .eq('id', id)
      } catch (error) {
        console.warn('更新标签使用统计失败:', error)
      }
    }

    // 保存到搜索历史
    try {
      const history = JSON.parse(localStorage.getItem('searchHistory') || '[]')
      const newHistory = [name, ...history.filter((item: string) => item !== name)].slice(0, 10)
      localStorage.setItem('searchHistory', JSON.stringify(newHistory))
    } catch (error) {
      console.warn('保存搜索历史失败:', error)
    }

    // 执行自定义点击处理
    if (onClick) {
      onClick()
    } else {
      // 默认导航到标签页面
      navigate(`/tags/${encodeURIComponent(name)}`)
      toast.success(`正在浏览 #${name} 相关内容`)
    }
  }

  const getCategoryColor = (category?: string) => {
    const colors = {
      anime: 'from-pink-100 to-pink-200 dark:from-pink-900 dark:to-pink-800',
      game: 'from-blue-100 to-blue-200 dark:from-blue-900 dark:to-blue-800',
      cosplay: 'from-purple-100 to-purple-200 dark:from-purple-900 dark:to-purple-800',
      illustration: 'from-green-100 to-green-200 dark:from-green-900 dark:to-green-800',
      figure: 'from-yellow-100 to-yellow-200 dark:from-yellow-900 dark:to-yellow-800',
      default: 'from-pink-100 to-blue-100 dark:from-pink-900 dark:to-blue-900'
    }
    
    return colors[category as keyof typeof colors] || colors.default
  }

  const getTextColor = (category?: string) => {
    const colors = {
      anime: 'text-pink-700 dark:text-pink-300',
      game: 'text-blue-700 dark:text-blue-300',
      cosplay: 'text-purple-700 dark:text-purple-300',
      illustration: 'text-green-700 dark:text-green-300',
      figure: 'text-yellow-700 dark:text-yellow-300',
      default: 'text-pink-700 dark:text-pink-300'
    }
    
    return colors[category as keyof typeof colors] || colors.default
  }

  const baseClasses = `inline-flex items-center space-x-1 rounded-full font-medium transition-all duration-200 ${
    clickable ? 'cursor-pointer hover:scale-105 active:scale-95' : 'cursor-default'
  } bg-gradient-to-r ${getCategoryColor(category)} ${getTextColor(category)} ${sizeClasses[size]} ${
    isClicked ? 'scale-95 shadow-inner' : 'shadow-sm hover:shadow-md'
  } ${className}`

  const FollowButton = () => {
    if (!showFollowButton || !user || !id) return null
    
    return (
      <button
        onClick={handleFollow}
        disabled={isLoading}
        className={`
          ml-1 flex items-center justify-center rounded-full transition-all duration-200
          ${isFollowed 
            ? 'bg-red-500 hover:bg-red-600 text-white' 
            : 'bg-white hover:bg-gray-100 text-gray-600'
          }
          ${size === 'sm' ? 'w-5 h-5' : size === 'lg' ? 'w-6 h-6' : 'w-5 h-5'}
          ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}
          shadow-sm hover:shadow-md
        `}
        title={isFollowed ? '取消关注' : '关注标签'}
      >
        {isLoading ? (
          <div className={`${size === 'sm' ? 'w-3 h-3' : 'w-4 h-4'} border-2 border-current border-t-transparent rounded-full animate-spin`} />
        ) : isFollowed ? (
          <Heart className={`${size === 'sm' ? 'w-3 h-3' : 'w-4 h-4'} fill-current`} />
        ) : (
          <HeartOff className={`${size === 'sm' ? 'w-3 h-3' : 'w-4 h-4'}`} />
        )}
      </button>
    )
  }

  return (
    <div className="inline-flex items-center">
      <Link
        to={`/tags/${encodeURIComponent(name)}`}
        onClick={handleClick}
        className={baseClasses}
        title={`浏览 #${name} 相关内容${category ? ` - ${category}` : ''}${
          showStats && usageCount > 0 ? ` (${usageCount} 次使用)` : ''
        }${showStats && followersCount > 0 ? ` (${followersCount} 人关注)` : ''}`}
      >
        <Hash className={`${size === 'sm' ? 'w-3 h-3' : 'w-4 h-4'} flex-shrink-0`} />
        <span className="truncate">{name}</span>
        
        {showStats && usageCount > 0 && (
          <div className="flex items-center space-x-1 ml-1">
            <Eye className={`${size === 'sm' ? 'w-3 h-3' : 'w-3 h-3'} opacity-70`} />
            <span className="text-xs opacity-80">{usageCount}</span>
          </div>
        )}
        
        {showStats && followersCount > 0 && (
          <div className="flex items-center space-x-1 ml-1">
            <Heart className={`${size === 'sm' ? 'w-3 h-3' : 'w-3 h-3'} opacity-70`} />
            <span className="text-xs opacity-80">{followersCount}</span>
          </div>
        )}
      </Link>
      {/* 只在特定场景下显示关注按钮，不在主页标签云显示 */}
      {showFollowButton && <FollowButton />}
    </div>
  )
}

/**
 * 标签云组件
 */
interface TagCloudProps {
  tags: Array<{
    id: string
    name: string
    usage_count: number
    followers_count?: number
    category?: string
  }>
  maxTags?: number
  showCount?: boolean
  size?: 'sm' | 'md' | 'lg'
  showFollowButton?: boolean
  onTagFollowChange?: (tagId: string, isFollowed: boolean) => void
}

export function TagCloud({ 
  tags, 
  maxTags = 20, 
  showCount = false, 
  size = 'md',
  showFollowButton = false,
  onTagFollowChange
}: TagCloudProps) {
  if (!tags || tags.length === 0) {
    return (
      <div className="text-center text-gray-500 dark:text-gray-400 py-8">
        暂无标签
      </div>
    )
  }

  // 按使用次数排序并限制数量
  const displayTags = tags
    .sort((a, b) => (b.usage_count || 0) - (a.usage_count || 0))
    .slice(0, maxTags)

  return (
    <div className="flex flex-wrap gap-3 justify-center">
      {displayTags.map((tag) => (
        <EnhancedTag
          key={tag.id}
          id={tag.id}
          name={tag.name}
          usageCount={tag.usage_count}
          followersCount={tag.followers_count}
          category={tag.category}
          size={size}
          showStats={showCount}
          showFollowButton={showFollowButton}
          onFollowChange={(isFollowed) => onTagFollowChange?.(tag.id, isFollowed)}
        />
      ))}
    </div>
  )
}

/**
 * 热门标签组件
 */
interface PopularTagsProps {
  limit?: number
  showCount?: boolean
  category?: string
  showFollowButton?: boolean
  onTagFollowChange?: (tagId: string, isFollowed: boolean) => void
}

export function PopularTags({ 
  limit = 10, 
  showCount = false, 
  category,
  showFollowButton = false,
  onTagFollowChange
}: PopularTagsProps) {
  const [tags, setTags] = useState<Array<{
    id: string
    name: string
    usage_count: number
    followers_count?: number
    category?: string
  }>>([])
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    fetchPopularTags()
  }, [category, limit])

  const fetchPopularTags = async () => {
    try {
      setIsLoading(true)
      let query = supabase
        .from('tags')
        .select('id, name, usage_count, followers_count, category')
        .order('usage_count', { ascending: false })
        .limit(limit)

      if (category) {
        query = query.eq('category', category)
      }

      const { data, error } = await query

      if (error) {
        console.error('获取热门标签失败:', error)
        return
      }

      setTags(data || [])
    } catch (error) {
      console.error('获取热门标签失败:', error)
    } finally {
      setIsLoading(false)
    }
  }

  if (isLoading) {
    return (
      <div className="flex flex-wrap gap-2 justify-center">
        {[...Array(6)].map((_, i) => (
          <div key={i} className="px-3 py-1 bg-gray-200 dark:bg-gray-700 rounded-full animate-pulse">
            <div className="w-16 h-4 bg-gray-300 dark:bg-gray-600 rounded"></div>
          </div>
        ))}
      </div>
    )
  }

  return <TagCloud 
    tags={tags} 
    showCount={showCount} 
    size="md" 
    showFollowButton={showFollowButton}
    onTagFollowChange={onTagFollowChange}
  />
}