import { useState, useEffect } from 'react';
import { X, Smartphone, Info, Heart } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

interface PWAInstallPrompt {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

export function DebugPWAInstallPrompt() {
  const [isInstallable, setIsInstallable] = useState(false);
  const [isInstalled, setIsInstalled] = useState(false);
  const [installPrompt, setInstallPrompt] = useState<PWAInstallPrompt | null>(null);
  const [isIOS, setIsIOS] = useState(false);
  const [showPrompt, setShowPrompt] = useState(false);
  const [debugInfo, setDebugInfo] = useState<string[]>([]);
  const [serviceWorkerReady, setServiceWorkerReady] = useState(false);

  // 调试信息收集
  const addDebugInfo = (info: string) => {
    setDebugInfo(prev => [...prev, `${new Date().toLocaleTimeString()}: ${info}`]);
  };

  useEffect(() => {
    addDebugInfo('PWA Debug: 开始检测');
    
    // 检测是否为iOS设备
    const userAgent = window.navigator.userAgent.toLowerCase();
    const isIOSDevice = /iphone|ipad|ipod/.test(userAgent);
    setIsIOS(isIOSDevice);
    addDebugInfo(`设备检测: ${isIOSDevice ? 'iOS设备' : '非iOS设备'}`);

    // 检测是否已经安装
    const checkInstalled = () => {
      const isStandalone = window.matchMedia('(display-mode: standalone)').matches;
      const isInstalledCheck = isStandalone || 
        (window.navigator as any).standalone === true ||
        document.referrer.includes('android-app://');
      
      setIsInstalled(isInstalledCheck);
      addDebugInfo(`安装状态: ${isInstalledCheck ? '已安装' : '未安装'}`);
      return isInstalledCheck;
    };

    // 注册service worker
    if ('serviceWorker' in navigator) {
      addDebugInfo('Service Worker: 支持检测通过');
      navigator.serviceWorker
        .register('/sw.js')
        .then((registration) => {
          addDebugInfo(`Service Worker: 注册成功 - ${registration.scope}`);
          setServiceWorkerReady(true);
        })
        .catch((error) => {
          addDebugInfo(`Service Worker: 注册失败 - ${error.message}`);
        });
    } else {
      addDebugInfo('Service Worker: 不支持');
    }

    // 监听安装提示事件
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      addDebugInfo('安装提示: beforeinstallprompt事件触发');
      setInstallPrompt(e as unknown as PWAInstallPrompt);
      setIsInstallable(true);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    // 检查manifest
    const checkManifest = async () => {
      try {
        const manifestLink = document.querySelector('link[rel="manifest"]');
        if (manifestLink) {
          addDebugInfo('Manifest: 检测到链接');
          const response = await fetch('/manifest.json');
          if (response.ok) {
            const manifest = await response.json();
            addDebugInfo(`Manifest: 加载成功 - ${manifest.name}`);
          } else {
            addDebugInfo(`Manifest: 加载失败 - ${response.status}`);
          }
        } else {
          addDebugInfo('Manifest: 未检测到链接');
        }
      } catch (error) {
        addDebugInfo(`Manifest: 错误 - ${error}`);
      }
    };

    // 延迟检查
    const timer = setTimeout(() => {
      const installed = checkInstalled();
      checkManifest();
      
      if (!installed) {
        addDebugInfo('准备显示安装提示');
        setShowPrompt(true);
      }
    }, 3000); // 3秒后显示，更快看到效果

    return () => {
      clearTimeout(timer);
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, []);

  const handleInstall = async () => {
    addDebugInfo('安装: 开始处理');
    if (installPrompt) {
      try {
        await installPrompt.prompt();
        const { outcome } = await installPrompt.userChoice;
        addDebugInfo(`安装: 用户选择 - ${outcome}`);
        if (outcome === 'accepted') {
          setIsInstalled(true);
          setIsInstallable(false);
        }
      } catch (error) {
        addDebugInfo(`安装: 错误 - ${error}`);
      }
    } else {
      addDebugInfo('安装: 没有可用的安装提示');
    }
  };

  const handleClose = () => {
    setShowPrompt(false);
    addDebugInfo('安装提示: 用户关闭');
  };

  return (
    <>
      <AnimatePresence>
        {showPrompt && (
          <motion.div
            initial={{ opacity: 0, y: 100 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 100 }}
            className="fixed bottom-4 left-4 right-4 z-50 md:left-auto md:right-4 md:w-96"
          >
            <div className="bg-gradient-to-r from-blue-500 to-purple-600 rounded-2xl shadow-2xl p-4 text-white">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center space-x-3">
                  <Smartphone className="w-6 h-6" />
                  <div>
                    <h3 className="font-bold text-lg">PWA安装测试</h3>
                    <p className="text-sm opacity-90">点击安装或查看调试信息</p>
                  </div>
                </div>
                <button
                  onClick={handleClose}
                  className="p-1 hover:bg-white/20 rounded-full transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>
              
              <div className="space-y-2 mb-4">
                <div className="text-xs bg-white/20 rounded-lg p-2">
                  <div>Service Worker: {serviceWorkerReady ? '✅ 已注册' : '❌ 未注册'}</div>
                  <div>可安装: {isInstallable ? '✅ 是' : '❌ 否'}</div>
                  <div>已安装: {isInstalled ? '✅ 是' : '❌ 否'}</div>
                  <div>设备: {isIOS ? '🍎 iOS' : '🤖 非iOS'}</div>
                </div>
              </div>
              
              <div className="flex space-x-3">
                <button
                  onClick={handleInstall}
                  disabled={!isInstallable}
                  className="flex-1 bg-white text-blue-600 font-semibold py-2 px-4 rounded-xl hover:bg-gray-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isInstallable ? '安装应用' : '不可安装'}
                </button>
                <button
                  onClick={() => setDebugInfo([])}
                  className="px-3 py-2 text-white hover:bg-white/20 rounded-xl transition-colors"
                >
                  <Info className="w-4 h-4" />
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 调试信息面板 */}
      {debugInfo.length > 0 && (
        <div className="fixed top-4 right-4 w-80 bg-black/80 text-white text-xs rounded-lg p-4 max-h-64 overflow-y-auto z-40">
          <div className="flex items-center justify-between mb-2">
            <span className="font-bold">🔍 PWA调试信息</span>
            <button
              onClick={() => setDebugInfo([])}
              className="text-white/60 hover:text-white"
            >
              ✕
            </button>
          </div>
          {debugInfo.map((info, index) => (
            <div key={index} className="mb-1 text-white/80">
              {info}
            </div>
          ))}
        </div>
      )}
    </>
  );
}