import { Heart, MessageCircle, Bookmark, Share2, MoreHorizontal, Edit3, Trash2, UserX, Tag } from 'lucide-react'
import { Link, useNavigate } from 'react-router-dom'
import { Post } from '../types'
import { useState } from 'react'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { PostDetailModal } from './PostDetailModal'
import { ShareModal } from './ShareModal'
import { useAuth } from '../contexts/AuthContext'
import { EnhancedTag } from './EnhancedTag'
import { ImageViewer } from './ImageViewer'
import { BlockUserButton } from './BlockUserButton'
import { BlockTagButton } from './BlockTagButton'

interface PostCardProps {
  post: Post
  onLike?: (postId: string) => void
  onComment?: (postId: string) => void
  onShare?: (postId: string) => void
  onEdit?: (post: Post) => void
  onDelete?: (postId: string) => void
}

export function PostCard({ post, onLike, onComment, onShare, onEdit, onDelete }: PostCardProps) {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [isLiked, setIsLiked] = useState(post.is_liked)
  const [isFavorited, setIsFavorited] = useState(post.is_favorited)
  const [likesCount, setLikesCount] = useState(post.likes_count)
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false)
  const [showMoreMenu, setShowMoreMenu] = useState(false)
  const [isShareModalOpen, setIsShareModalOpen] = useState(false)
  const [isProcessingLike, setIsProcessingLike] = useState(false)
  const [isProcessingFavorite, setIsProcessingFavorite] = useState(false)
  const [isImageViewerOpen, setIsImageViewerOpen] = useState(false)
  const [currentImageIndex, setCurrentImageIndex] = useState(0)

  const handleLike = async () => {
    if (isProcessingLike) return
    
    try {
      setIsProcessingLike(true)
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        toast.error('请先登录')
        return
      }

      if (isLiked) {
        // 立即更新UI状态
        setIsLiked(false)
        setLikesCount(prev => prev - 1)
        
        const { error } = await supabase
          .from('likes')
          .delete()
          .eq('user_id', user.id)
          .eq('post_id', post.id)
        
        if (error) {
          console.error('取消点赞失败:', error)
          // 如果失败，恢复状态
          setIsLiked(true)
          setLikesCount(prev => prev + 1)
          throw error
        }
        
        toast.success('取消点赞')
      } else {
        // 立即更新UI状态
        setIsLiked(true)
        setLikesCount(prev => prev + 1)
        
        const { error } = await supabase
          .from('likes')
          .insert({
            user_id: user.id,
            post_id: post.id
          })
        
        if (error) {
          console.error('点赞失败:', error)
          // 如果失败，恢复状态
          setIsLiked(false)
          setLikesCount(prev => prev - 1)
          throw error
        }
        
        toast.success('点赞成功')
      }
      
      onLike?.(post.id)
    } catch (error: any) {
      console.error('点赞操作失败:', error)
      toast.error(error.message || '操作失败，请稍后重试')
    } finally {
      setIsProcessingLike(false)
    }
  }

  const handleFavorite = async () => {
    if (isProcessingFavorite) return
    
    try {
      setIsProcessingFavorite(true)
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        toast.error('请先登录')
        return
      }

      if (isFavorited) {
        // 立即更新UI状态
        setIsFavorited(false)
        
        const { error } = await supabase
          .from('favorites')
          .delete()
          .eq('user_id', user.id)
          .eq('post_id', post.id)
        
        if (error) {
          console.error('取消收藏失败:', error)
          // 如果失败，恢复状态
          setIsFavorited(true)
          throw error
        }
        
        toast.success('取消收藏')
      } else {
        // 立即更新UI状态
        setIsFavorited(true)
        
        const { error } = await supabase
          .from('favorites')
          .insert({
            user_id: user.id,
            post_id: post.id
          })
        
        if (error) {
          console.error('收藏失败:', error)
          // 如果失败，恢复状态
          setIsFavorited(false)
          throw error
        }
        
        toast.success('收藏成功')
      }
    } catch (error: any) {
      console.error('收藏操作失败:', error)
      toast.error(error.message || '操作失败，请稍后重试')
    } finally {
      setIsProcessingFavorite(false)
    }
  }

  const handleEdit = () => {
    setShowMoreMenu(false)
    onEdit?.(post)
  }

  const handleDelete = async () => {
    if (!confirm('确定要删除这条帖子吗？此操作不可恢复。')) return
    
    try {
      setShowMoreMenu(false)
      const { error } = await supabase
        .from('posts')
        .delete()
        .eq('id', post.id)
        .eq('user_id', user?.id)

      if (error) throw error

      toast.success('帖子删除成功')
      onDelete?.(post.id)
    } catch (error) {
      console.error('删除帖子失败:', error)
      toast.error('删除帖子失败')
    }
  }

  const handleShare = () => {
    setIsShareModalOpen(true)
    onShare?.(post.id)
  }

  const handleNavigateToDetail = () => {
    navigate(`/post/${post.id}`)
  }

  const handleImageClick = (index: number) => {
    setCurrentImageIndex(index)
    setIsImageViewerOpen(true)
  }

  const isOwner = user?.id === post.user.id

  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl sm:rounded-2xl md:rounded-3xl shadow-lg overflow-hidden hover:shadow-xl transition-all duration-300 transform hover:scale-105">
      <div className="p-3 sm:p-4 md:p-6 pb-2 sm:pb-3 md:pb-4">
        <Link to={`/u/${post.user.id}`} className="flex items-center space-x-2 sm:space-x-3">
          <img
            src={post.user.avatar_url || 'https://api.dicebear.com/7.x/avataaars/svg?seed=' + post.user.username}
            alt={post.user.username}
            className="w-8 h-8 sm:w-10 sm:h-10 md:w-12 md:h-12 rounded-full object-cover flex-shrink-0"
          />
          <div className="flex-1 min-w-0">
            <h3 className="font-semibold text-gray-800 dark:text-gray-200 hover:text-pink-600 text-xs sm:text-sm md:text-base truncate">{post.user.username}</h3>
            <p className="text-xs text-gray-500 dark:text-gray-400">
              {new Date(post.created_at).toLocaleDateString('zh-CN')}
            </p>
          </div>
        </Link>
      </div>

      {/* 内容 */}
      <div className="px-3 sm:px-4 md:px-6 pb-2 sm:pb-3 md:pb-4">
        {/* 标题显示 */}
        {post.title && (
          <h3 
            className="text-base sm:text-lg font-bold text-gray-800 dark:text-gray-200 mb-1 sm:mb-2 cursor-pointer hover:text-pink-600 dark:hover:text-pink-400 transition-colors"
            onClick={handleNavigateToDetail}
          >
            {post.title}
          </h3>
        )}
        
        {/* 副标题显示 */}
        {post.subtitle && (
          <p 
            className="text-gray-600 dark:text-gray-400 mb-2 sm:mb-3 md:mb-4 text-sm md:text-base leading-relaxed cursor-pointer hover:text-pink-600 dark:hover:text-pink-400 transition-colors"
            onClick={handleNavigateToDetail}
          >
            {post.subtitle}
          </p>
        )}
        
        {/* 主要内容 */}
        <p 
          className="text-gray-800 dark:text-gray-200 mb-2 sm:mb-3 md:mb-4 text-sm md:text-base leading-relaxed cursor-pointer hover:text-pink-600 dark:hover:text-pink-400 transition-colors"
          onClick={handleNavigateToDetail}
        >
          {post.content}
        </p>
        
        {/* 媒体展示 */}
        {((Array.isArray(post.images) && post.images.length > 0) || (Array.isArray(post.videos) && post.videos.length > 0)) && (
          <div className="mb-2 sm:mb-3 md:mb-4">
            {/* 图片展示 */}
            {Array.isArray(post.images) && post.images.length > 0 && (
              <div className={`grid gap-1 sm:gap-2 ${post.images.length === 1 ? 'grid-cols-1' : 'grid-cols-2'}`}>
                {post.images.slice(0, 4).map((image, index) => (
                  <div 
                    key={`img-${index}`} 
                    className={`rounded-lg sm:rounded-xl overflow-hidden ${post.images.length === 1 ? 'aspect-video' : 'aspect-square'} cursor-pointer relative group`}
                    onClick={() => handleImageClick(index)}
                  >
                    <img
                      src={image}
                      alt={`图片 ${index + 1}`}
                      className="w-full h-full object-cover hover:scale-110 transition-transform duration-300"
                      draggable={false}
                      onContextMenu={(e) => {
                        // Prevent right-click download if user has disabled downloads
                        const preventDownload = localStorage.getItem('preventImageDownload') === 'true'
                        if (preventDownload) {
                          e.preventDefault()
                        }
                      }}
                    />
                    <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-20 transition-all duration-300 flex items-center justify-center">
                      <div className="opacity-0 group-hover:opacity-100 transition-opacity duration-300 bg-black bg-opacity-50 text-white px-2 sm:px-3 py-1 rounded-full text-xs sm:text-sm">
                        点击查看
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
            
            {/* 视频展示 */}
            {Array.isArray(post.videos) && post.videos.length > 0 && (
              <div className={`grid gap-2 mt-2 ${post.videos.length === 1 ? 'grid-cols-1' : 'grid-cols-2'}`}>
                {post.videos.slice(0, 2).map((video, index) => (
                  <div 
                    key={`video-${index}`} 
                    className={`rounded-xl overflow-hidden ${post.videos.length === 1 ? 'aspect-video' : 'aspect-square'} bg-gray-900 cursor-pointer`}
                    onClick={handleNavigateToDetail}
                  >
                    <video
                      src={video}
                      className="w-full h-full object-cover"
                      controls
                      muted
                      playsInline
                    />
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* 标签 */}
        {Array.isArray(post.tags) && post.tags.length > 0 && (
          <div className="flex flex-wrap gap-2 mb-3 md:mb-4">
            {post.tags.map((tag) => (
              <div key={tag.id} className="flex items-center space-x-1">
                <EnhancedTag
                  id={tag.id}
                  name={tag.name}
                  usageCount={tag.usage_count}
                  category={tag.category}
                  size="sm"
                  showStats={false}
                />
                <BlockTagButton
                  tagId={tag.id}
                  tagName={tag.name}
                  variant="chip"
                  size="sm"
                />
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 互动按钮 */}
      <div className="px-3 sm:px-4 md:px-6 pb-3 sm:pb-4 md:pb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3 sm:space-x-4 md:space-x-6">
            <button
                onClick={handleLike}
                disabled={isProcessingLike}
                className={`flex items-center space-x-1 sm:space-x-2 transition-all duration-200 ${
                  isLiked ? 'text-red-500' : 'text-gray-500 dark:text-gray-400 hover:text-red-500'
                } ${isProcessingLike ? 'opacity-50 cursor-not-allowed' : 'hover:scale-110'}`}
              >
              <Heart className={`w-4 h-4 sm:w-5 sm:h-5 ${isLiked ? 'fill-current' : ''} ${isProcessingLike ? 'animate-pulse' : ''}`} />
              <span className="text-xs sm:text-sm font-medium">{likesCount}</span>
            </button>
            
            <button
              onClick={handleNavigateToDetail}
              className="flex items-center space-x-1 sm:space-x-2 text-gray-500 dark:text-gray-400 hover:text-blue-500 transition-all duration-200 hover:scale-110"
            >
              <MessageCircle className="w-4 h-4 sm:w-5 sm:h-5" />
              <span className="text-xs sm:text-sm font-medium">{post.comments_count}</span>
            </button>
            
            <button
              onClick={handleFavorite}
              disabled={isProcessingFavorite}
              className={`flex items-center space-x-1 transition-all duration-200 ${
                isFavorited ? 'text-yellow-500' : 'text-gray-500 dark:text-gray-400 hover:text-yellow-500'
              } ${isProcessingFavorite ? 'opacity-50 cursor-not-allowed' : 'hover:scale-110'}`}
            >
              <Bookmark className={`w-4 h-4 sm:w-5 sm:h-5 ${isFavorited ? 'fill-current' : ''} ${isProcessingFavorite ? 'animate-pulse' : ''}`} />
            </button>
          </div>
          
          <div className="flex items-center space-x-2 relative">
            {/* 拉黑用户按钮 */}
            {user && user.id !== post.user.id && (
              <BlockUserButton
                targetUserId={post.user.id}
                targetUserName={post.user.username}
                variant="icon"
                size="sm"
              />
            )}
            
            <button
              onClick={handleShare}
              className="text-gray-500 dark:text-gray-400 hover:text-green-500 transition-colors p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700"
              aria-label="分享"
            >
              <Share2 className="w-4 h-4 sm:w-5 sm:h-5" />
            </button>
            
            {isOwner && (
              <div className="relative">
                <button 
                  onClick={() => setShowMoreMenu(!showMoreMenu)}
                  className="text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 transition-colors p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700"
                  aria-label="更多选项"
                >
                  <MoreHorizontal className="w-4 h-4 sm:w-5 sm:h-5" />
                </button>
                
                {showMoreMenu && (
                  <>
                    {/* 点击外部关闭菜单 */}
                    <div 
                      className="fixed inset-0 z-10" 
                      onClick={() => setShowMoreMenu(false)}
                    />
                    <div className="absolute right-0 top-8 bg-white dark:bg-gray-800 rounded-xl shadow-xl border border-gray-200 dark:border-gray-600 py-2 z-20 min-w-[120px] sm:min-w-[140px] animate-in fade-in duration-200">
                      <div className="px-1 sm:px-2 py-1">
                        <button
                          onClick={handleEdit}
                          className="w-full px-2 sm:px-3 py-2 text-left text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg flex items-center space-x-2 sm:space-x-3 transition-colors"
                        >
                          <Edit3 className="w-3 h-3 sm:w-4 sm:h-4 text-gray-500" />
                          <span>编辑帖子</span>
                        </button>
                        <button
                          onClick={handleDelete}
                          className="w-full px-2 sm:px-3 py-2 text-left text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg flex items-center space-x-2 sm:space-x-3 transition-colors"
                        >
                          <Trash2 className="w-3 h-3 sm:w-4 sm:h-4 text-red-500" />
                          <span>删除帖子</span>
                        </button>
                      </div>
                    </div>
                  </>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 帖子详情模态框 */}
      <PostDetailModal
        post={post}
        isOpen={isDetailModalOpen}
        onClose={() => setIsDetailModalOpen(false)}
      />

      {/* 分享模态框 */}
      <ShareModal
        postId={post.id}
        postContent={post.content}
        isOpen={isShareModalOpen}
        onClose={() => setIsShareModalOpen(false)}
      />

      {/* 图片查看器 */}
      {isImageViewerOpen && (
        <ImageViewer
          images={post.images || []}
          currentIndex={currentImageIndex}
          onClose={() => setIsImageViewerOpen(false)}
          preventDownload={localStorage.getItem('preventImageDownload') === 'true'}
        />
      )}
    </div>
  )
}