import { useState, useEffect } from 'react'
import { X, Download, ZoomIn, ZoomOut, Maximize2 } from 'lucide-react'

interface ImageViewerProps {
  images: string[]
  currentIndex?: number
  onClose: () => void
  preventDownload?: boolean
}

export function ImageViewer({ images, currentIndex = 0, onClose, preventDownload: externalPreventDownload = false }: ImageViewerProps) {
  const [preventDownload, setPreventDownload] = useState(externalPreventDownload)

  useEffect(() => {
    // Check user's download protection setting
    const userPreventDownload = localStorage.getItem('preventImageDownload') === 'true'
    setPreventDownload(externalPreventDownload || userPreventDownload)
  }, [externalPreventDownload])
  const [currentImageIndex, setCurrentImageIndex] = useState(currentIndex)
  const [zoom, setZoom] = useState(1)
  const [isDragging, setIsDragging] = useState(false)
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 })
  const [imagePosition, setImagePosition] = useState({ x: 0, y: 0 })

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      switch (e.key) {
        case 'Escape':
          onClose()
          break
        case 'ArrowLeft':
          navigateImage('prev')
          break
        case 'ArrowRight':
          navigateImage('next')
          break
        case '+':
        case '=':
          e.preventDefault()
          setZoom(prev => Math.min(prev + 0.2, 3))
          break
        case '-':
          e.preventDefault()
          setZoom(prev => Math.max(prev - 0.2, 0.5))
          break
      }
    }

    document.addEventListener('keydown', handleKeyDown)
    document.body.style.overflow = 'hidden'

    return () => {
      document.removeEventListener('keydown', handleKeyDown)
      document.body.style.overflow = 'unset'
    }
  }, [])

  const navigateImage = (direction: 'prev' | 'next') => {
    if (direction === 'prev') {
      setCurrentImageIndex(prev => (prev > 0 ? prev - 1 : images.length - 1))
    } else {
      setCurrentImageIndex(prev => (prev < images.length - 1 ? prev + 1 : 0))
    }
    // Reset zoom and position when changing images
    setZoom(1)
    setImagePosition({ x: 0, y: 0 })
  }

  const handleMouseDown = (e: React.MouseEvent) => {
    if (zoom > 1) {
      setIsDragging(true)
      setDragStart({ x: e.clientX - imagePosition.x, y: e.clientY - imagePosition.y })
    }
  }

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging && zoom > 1) {
      setImagePosition({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      })
    }
  }

  const handleMouseUp = () => {
    setIsDragging(false)
  }

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault()
    const delta = e.deltaY > 0 ? -0.1 : 0.1
    setZoom(prev => Math.max(0.5, Math.min(3, prev + delta)))
  }

  const handleDownload = (e: React.MouseEvent) => {
    if (preventDownload) {
      e.preventDefault()
      e.stopPropagation()
      return
    }

    const link = document.createElement('a')
    link.href = images[currentImageIndex]
    link.download = `image-${currentImageIndex + 1}.jpg`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
  }

  const currentImage = images[currentImageIndex]

  // Add comprehensive download protection
  useEffect(() => {
    if (preventDownload) {
      // Disable context menu
      const handleContextMenu = (e: Event) => {
        e.preventDefault()
        return false
      }
      
      // Disable drag and drop
      const handleDragStart = (e: Event) => {
        e.preventDefault()
        return false
      }

      // Disable keyboard shortcuts for saving
      const handleKeyDown = (e: KeyboardEvent) => {
        if ((e.ctrlKey || e.metaKey) && (e.key === 's' || e.key === 'S')) {
          e.preventDefault()
          return false
        }
      }

      document.addEventListener('contextmenu', handleContextMenu)
      document.addEventListener('dragstart', handleDragStart)
      document.addEventListener('keydown', handleKeyDown)

      return () => {
        document.removeEventListener('contextmenu', handleContextMenu)
        document.removeEventListener('dragstart', handleDragStart)
        document.removeEventListener('keydown', handleKeyDown)
      }
    }
  }, [preventDownload])

  return (
    <div className="fixed inset-0 z-50 bg-black bg-opacity-95 flex items-center justify-center">
      {/* Close overlay */}
      <div className="absolute inset-0" onClick={onClose} />
      
      {/* Image container */}
      <div 
        className="relative max-w-full max-h-full flex items-center justify-center cursor-pointer select-none"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onWheel={handleWheel}
        style={{
          transform: `translate(${imagePosition.x}px, ${imagePosition.y}px)`
        }}
      >
        <img
          src={currentImage}
          alt={`Image ${currentImageIndex + 1}`}
          className={`max-w-full max-h-full object-contain transition-transform duration-200 ${preventDownload ? 'select-none pointer-events-none' : ''}`}
          style={{ 
            transform: `scale(${zoom})`,
            userSelect: preventDownload ? 'none' : 'auto',
            WebkitUserSelect: preventDownload ? 'none' : 'auto',
            MozUserSelect: preventDownload ? 'none' : 'auto',
            msUserSelect: preventDownload ? 'none' : 'text'
          }}
          draggable={false}
          onContextMenu={(e) => preventDownload && e.preventDefault()}
        />
      </div>

      {/* Navigation arrows */}
      {images.length > 1 && (
        <>
          <button
            onClick={() => navigateImage('prev')}
            className="absolute left-4 top-1/2 transform -translate-y-1/2 bg-black bg-opacity-50 text-white p-3 rounded-full hover:bg-opacity-70 transition-all z-10"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <button
            onClick={() => navigateImage('next')}
            className="absolute right-4 top-1/2 transform -translate-y-1/2 bg-black bg-opacity-50 text-white p-3 rounded-full hover:bg-opacity-70 transition-all z-10"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </button>
        </>
      )}

      {/* Controls */}
      <div className="absolute top-4 right-4 flex space-x-2 z-10">
        <button
          onClick={() => setZoom(prev => Math.max(0.5, prev - 0.2))}
          className="bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition-all"
          disabled={zoom <= 0.5}
        >
          <ZoomOut className="w-5 h-5" />
        </button>
        <button
          onClick={() => setZoom(1)}
          className="bg-black bg-opacity-50 text-white px-3 py-2 rounded-full hover:bg-opacity-70 transition-all text-sm font-medium"
        >
          {Math.round(zoom * 100)}%
        </button>
        <button
          onClick={() => setZoom(prev => Math.min(3, prev + 0.2))}
          className="bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition-all"
          disabled={zoom >= 3}
        >
          <ZoomIn className="w-5 h-5" />
        </button>
        {!preventDownload && (
          <button
            onClick={handleDownload}
            className="bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition-all"
          >
            <Download className="w-5 h-5" />
          </button>
        )}
        <button
          onClick={onClose}
          className="bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition-all"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Image counter */}
      {images.length > 1 && (
        <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 bg-black bg-opacity-50 text-white px-4 py-2 rounded-full text-sm">
          {currentImageIndex + 1} / {images.length}
        </div>
      )}

      {/* Image name */}
      <div className="absolute bottom-4 right-4 bg-black bg-opacity-50 text-white px-4 py-2 rounded-full text-sm max-w-xs truncate">
        图片 {currentImageIndex + 1}
      </div>
    </div>
  )
}