import { useState } from 'react'
import { blockTag, unblockTag, isTagBlocked } from '../lib/blocking'
import { toast } from 'sonner'

interface BlockTagButtonProps {
  tagId: string
  tagName?: string
  size?: 'sm' | 'md' | 'lg'
  variant?: 'button' | 'chip'
  onBlockStatusChange?: (isBlocked: boolean) => void
}

export const BlockTagButton = ({ 
  tagId, 
  tagName = '此标签',
  size = 'md',
  variant = 'chip',
  onBlockStatusChange
}: BlockTagButtonProps) => {
  const [isBlocked, setIsBlocked] = useState(false)
  const [isLoading, setIsLoading] = useState(false)

  const handleBlockTag = async () => {
    setIsLoading(true)
    try {
      if (isBlocked) {
        await unblockTag(tagId)
        setIsBlocked(false)
        toast.success(`已取消屏蔽标签 "${tagName}"`)
        onBlockStatusChange?.(false)
      } else {
        await blockTag(tagId, '用户主动屏蔽')
        setIsBlocked(true)
        toast.success(`已屏蔽标签 "${tagName}"`)
        onBlockStatusChange?.(true)
      }
    } catch (error) {
      toast.error(isBlocked ? '取消屏蔽失败' : '屏蔽失败')
      console.error('屏蔽标签操作失败:', error)
    } finally {
      setIsLoading(false)
    }
  }

  if (variant === 'chip') {
    return (
      <button
        onClick={handleBlockTag}
        disabled={isLoading}
        className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium transition-colors ${
          isBlocked
            ? 'bg-red-100 text-red-800 border border-red-200 hover:bg-red-200'
            : 'bg-blue-100 text-blue-800 border border-blue-200 hover:bg-blue-200'
        } ${size === 'sm' ? 'text-xs px-2 py-0.5' : size === 'lg' ? 'text-base px-4 py-2' : ''} ${
          isLoading ? 'opacity-50 cursor-not-allowed' : ''
        }`}
        title={isBlocked ? '取消屏蔽标签' : '屏蔽标签'}
      >
        <span className="mr-1">{isBlocked ? '🚫' : '⛔'}</span>
        {tagName}
      </button>
    )
  }

  return (
    <button
      onClick={handleBlockTag}
      disabled={isLoading}
      className={`px-4 py-2 rounded-lg font-medium transition-colors ${
        isBlocked
          ? 'bg-red-500 text-white hover:bg-red-600'
          : 'bg-blue-500 text-white hover:bg-blue-600'
      } ${size === 'sm' ? 'text-sm px-3 py-1' : size === 'lg' ? 'text-lg px-6 py-3' : ''} ${
        isLoading ? 'opacity-50 cursor-not-allowed' : ''
      }`}
    >
      {isLoading ? (
        '处理中...'
      ) : isBlocked ? (
        '已屏蔽'
      ) : (
        '屏蔽标签'
      )}
    </button>
  )
}