import { useState } from 'react'
import { X, Link, Share2, MessageCircle, Facebook, Twitter, Copy, Check } from 'lucide-react'
import { toast } from 'sonner'

interface ShareModalProps {
  postId: string
  postContent: string
  isOpen: boolean
  onClose: () => void
}

export function ShareModal({ postId, postContent, isOpen, onClose }: ShareModalProps) {
  const [copied, setCopied] = useState(false)
  
  const shareUrl = `${window.location.origin}/post/${postId}`
  const shareText = `我在二次元小窝分享了一条动态：${postContent.slice(0, 50)}${postContent.length > 50 ? '...' : ''}`

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl)
      setCopied(true)
      toast.success('链接已复制到剪贴板')
      setTimeout(() => setCopied(false), 2000)
    } catch (error) {
      // 降级方案
      const textArea = document.createElement('textarea')
      textArea.value = shareUrl
      document.body.appendChild(textArea)
      textArea.select()
      document.execCommand('copy')
      document.body.removeChild(textArea)
      
      setCopied(true)
      toast.success('链接已复制到剪贴板')
      setTimeout(() => setCopied(false), 2000)
    }
  }

  const handleShareToWeChat = () => {
    // 微信分享通常需要微信 JS SDK，这里提供基础实现
    if (navigator.share) {
      navigator.share({
        title: '二次元小窝',
        text: shareText,
        url: shareUrl,
      }).catch(() => {
        toast.info('请手动复制链接分享')
      })
    } else {
      handleCopyLink()
    }
  }

  const handleShareToWeibo = () => {
    const weiboUrl = `https://service.weibo.com/share/share.php?url=${encodeURIComponent(shareUrl)}&title=${encodeURIComponent(shareText)}`
    window.open(weiboUrl, '_blank', 'width=600,height=400')
  }

  const handleShareToQQ = () => {
    const qqUrl = `https://connect.qq.com/widget/shareqq/index.html?url=${encodeURIComponent(shareUrl)}&title=${encodeURIComponent(shareText)}&summary=${encodeURIComponent(shareText)}`
    window.open(qqUrl, '_blank', 'width=600,height=400')
  }

  const handleShareToTwitter = () => {
    const twitterUrl = `https://twitter.com/intent/tweet?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(shareText)}`
    window.open(twitterUrl, '_blank', 'width=600,height=400')
  }

  const handleShareToFacebook = () => {
    const facebookUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`
    window.open(facebookUrl, '_blank', 'width=600,height=400')
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md max-h-[90vh] overflow-hidden">
        {/* 头部 */}
        <div className="flex items-center justify-between p-6 border-b">
          <h2 className="text-xl font-bold text-gray-800">分享</h2>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* 分享内容预览 */}
        <div className="p-6 border-b">
          <div className="bg-gray-50 rounded-xl p-4">
            <p className="text-gray-800 text-sm leading-relaxed">
              {shareText}
            </p>
            <p className="text-gray-500 text-xs mt-2 truncate">
              {shareUrl}
            </p>
          </div>
        </div>

        {/* 分享平台 */}
        <div className="p-6">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">分享到</h3>
          <div className="grid grid-cols-2 gap-4">
            {/* 微信 */}
            <button
              onClick={handleShareToWeChat}
              className="flex flex-col items-center p-4 bg-green-50 rounded-xl hover:bg-green-100 transition-colors"
            >
              <MessageCircle className="w-8 h-8 text-green-600 mb-2" />
              <span className="text-sm font-medium text-green-700">微信</span>
            </button>

            {/* 微博 */}
            <button
              onClick={handleShareToWeibo}
              className="flex flex-col items-center p-4 bg-red-50 rounded-xl hover:bg-red-100 transition-colors"
            >
              <div className="w-8 h-8 bg-red-600 rounded-full flex items-center justify-center mb-2">
                <span className="text-white text-xs font-bold">微</span>
              </div>
              <span className="text-sm font-medium text-red-700">微博</span>
            </button>

            {/* QQ */}
            <button
              onClick={handleShareToQQ}
              className="flex flex-col items-center p-4 bg-blue-50 rounded-xl hover:bg-blue-100 transition-colors"
            >
              <div className="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center mb-2">
                <span className="text-white text-xs font-bold">Q</span>
              </div>
              <span className="text-sm font-medium text-blue-700">QQ</span>
            </button>

            {/* Twitter */}
            <button
              onClick={handleShareToTwitter}
              className="flex flex-col items-center p-4 bg-sky-50 rounded-xl hover:bg-sky-100 transition-colors"
            >
              <Twitter className="w-8 h-8 text-sky-600 mb-2" />
              <span className="text-sm font-medium text-sky-700">Twitter</span>
            </button>

            {/* Facebook */}
            <button
              onClick={handleShareToFacebook}
              className="flex flex-col items-center p-4 bg-blue-50 rounded-xl hover:bg-blue-100 transition-colors"
            >
              <Facebook className="w-8 h-8 text-blue-600 mb-2" />
              <span className="text-sm font-medium text-blue-700">Facebook</span>
            </button>

            {/* 复制链接 */}
            <button
              onClick={handleCopyLink}
              className="flex flex-col items-center p-4 bg-gray-50 rounded-xl hover:bg-gray-100 transition-colors"
            >
              {copied ? (
                <Check className="w-8 h-8 text-green-600 mb-2" />
              ) : (
                <Link className="w-8 h-8 text-gray-600 mb-2" />
              )}
              <span className="text-sm font-medium text-gray-700">
                {copied ? '已复制' : '复制链接'}
              </span>
            </button>
          </div>
        </div>

        {/* 底部 */}
        <div className="border-t p-6">
          <button
            onClick={onClose}
            className="w-full bg-gray-100 text-gray-700 py-3 rounded-xl hover:bg-gray-200 transition-colors"
          >
            取消
          </button>
        </div>
      </div>
    </div>
  )
}