import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { PostCard } from '../components/PostCard'
import { CreatePostModal } from '../components/CreatePostModal'
import { PostEditModal } from '../components/PostEditModal'
import { UserMenu } from '../components/UserMenu'
import { SmartSearchBar } from '../components/SmartSearchBar'
import { ThemeToggle } from '../components/ThemeToggle'
import { PullToRefreshIndicator } from '../components/PullToRefreshIndicator'
import { FollowedTagsFeed } from '../components/FollowedTagsFeed'
import { PopularTags } from '../components/EnhancedTag'
import { usePullToRefresh } from '../hooks/usePullToRefresh'
import { useBlockedTags, useBlockedUsers } from '../hooks/useBlocking'
import { Post } from '../types'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { handleDatabaseError } from '../lib/database-utils'
import { useAuth } from '../contexts/AuthContext'
import { Search, Plus, Home, Compass, MessageCircle, User } from 'lucide-react'

export function HomePage() {
  const [posts, setPosts] = useState<Post[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false)
  const [isEditModalOpen, setIsEditModalOpen] = useState(false)
  const [editingPost, setEditingPost] = useState<Post | null>(null)
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'following' | 'recommended' | 'latest'>('recommended')
  const [activeCategory, setActiveCategory] = useState<'all' | 'dynamic' | 'article' | 'image' | 'novel' | 'comic'>('all')
  const { getBlockedTagIds } = useBlockedTags()
  const { getBlockedUserIds } = useBlockedUsers()

  const fetchPosts = async () => {
    let fallbackTimer: number | null = null
    try {
      setIsLoading(true)
      fallbackTimer = window.setTimeout(() => {
        console.log('加载超时，强制停止加载')
        setIsLoading(false)
      }, 5000)
      
      // 获取当前用户信息（可选）
      let user = null
      try {
        const { data: { user: currentUser } } = await supabase.auth.getUser()
        user = currentUser
        console.log('Current user:', user)
      } catch (authError) {
        console.warn('获取用户信息失败:', authError)
        // 继续执行，用户可能未登录
      }

      // 获取被屏蔽的用户ID列表
      const blockedUserIds = user ? await getBlockedUserIds() : []
      console.log('被屏蔽的用户ID列表:', blockedUserIds)

      // 获取被屏蔽的标签ID列表
      const blockedTagIds = user ? await getBlockedTagIds() : []
      console.log('被屏蔽的标签ID列表:', blockedTagIds)

      let query = supabase
        .from('posts')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(30)

      // 如果有被屏蔽的用户，排除这些用户的帖子
      if (blockedUserIds.length > 0 && user) {
        query = query.not('user_id', 'in', `(${blockedUserIds.join(',')})`)
      }

      const { data: postsData, error } = await query

      if (error) {
        console.error('获取帖子失败:', error)
        handleDatabaseError(error, 'fetchPosts')
        throw error
      }

      console.log('获取到帖子数量:', postsData?.length || 0)

      if (!postsData || postsData.length === 0) {
        console.log('没有找到帖子数据')
        setPosts([])
        return
      }

      // 如果有屏蔽的标签，需要进一步过滤包含这些标签的帖子
      let filteredPosts = postsData
      if (blockedTagIds.length > 0 && user) {
        // 获取这些帖子的标签信息
        const { data: postTagsData } = await supabase
          .from('post_tags')
          .select('post_id, tag_id')
          .in('post_id', postsData.map(p => p.id))

        if (postTagsData) {
          // 创建帖子ID到标签ID的映射
          const postTagMap = new Map<string, string[]>()
          postTagsData.forEach(pt => {
            if (!postTagMap.has(pt.post_id)) {
              postTagMap.set(pt.post_id, [])
            }
            postTagMap.get(pt.post_id)!.push(pt.tag_id)
          })

          // 过滤掉包含屏蔽标签的帖子
          filteredPosts = postsData.filter(post => {
            const postTags = postTagMap.get(post.id) || []
            return !postTags.some(tagId => blockedTagIds.includes(tagId))
          })

          // 过滤掉被屏蔽用户的内容
          const blockedUserIds = getBlockedUserIds()
          filteredPosts = filteredPosts.filter(post => !blockedUserIds.includes(post.user_id))

          console.log(`过滤后帖子数量: ${filteredPosts.length} (原始: ${postsData.length})`)
        }
      }

      // 获取用户信息和标签信息
      const postsWithDetails = await Promise.all(
        filteredPosts.map(async (post) => {
          try {
            // 获取用户信息
            const { data: userData, error: userError } = await supabase
              .from('users')
              .select('id, username, avatar_url')
              .eq('id', post.user_id)
              .single()

            if (userError) {
              console.warn(`获取用户 ${post.user_id} 信息失败:`, userError)
            }

            // 获取标签信息
            const { data: postTagsData, error: tagsError } = await supabase
              .from('post_tags')
              .select('tag:tags(id, name, category, usage_count)')
              .eq('post_id', post.id)

            if (tagsError) {
              console.warn(`获取帖子 ${post.id} 标签失败:`, tagsError)
            }

            let is_liked = false
            let is_favorited = false

            if (user) {
              try {
                // 检查是否点赞
                const { data: likeData } = await supabase
                  .from('likes')
                  .select('id')
                  .eq('user_id', user.id)
                  .eq('post_id', post.id)
                  .maybeSingle()
                
                is_liked = !!likeData

                // 检查是否收藏
                const { data: favoriteData } = await supabase
                  .from('favorites')
                  .select('id')
                  .eq('user_id', user.id)
                  .eq('post_id', post.id)
                  .maybeSingle()
                
                is_favorited = !!favoriteData
              } catch (authError) {
                console.warn('用户认证检查失败:', authError)
                // 用户可能未登录，继续处理
              }
            }

            return {
              ...post,
              user: userData || { id: post.user_id, username: '未知用户', avatar_url: null },
              tags: postTagsData?.map((pt: any) => pt.tag) || [],
              is_liked,
              is_favorited,
              images: Array.isArray(post.images) ? post.images : [],
              videos: Array.isArray(post.videos) ? post.videos : [],
              comments_count: post.comments_count || 0,
              likes_count: post.likes_count || 0
            }
          } catch (error) {
            console.error(`处理帖子 ${post.id} 时出错:`, error)
            return {
              id: post.id,
              user_id: post.user_id,
              content: post.content || '',
              images: Array.isArray(post.images) ? post.images : [],
              videos: Array.isArray(post.videos) ? post.videos : [],
              likes_count: post.likes_count || 0,
              comments_count: post.comments_count || 0,
              created_at: post.created_at,
              updated_at: post.updated_at,
              user: { id: post.user_id, username: '未知用户', avatar_url: null },
              tags: [],
              is_liked: false,
              is_favorited: false
            }
          }
        })
      )

      console.log('处理完成，设置帖子数据:', postsWithDetails.length)
      const shuffled = [...postsWithDetails]
      for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1))
        const t = shuffled[i]
        shuffled[i] = shuffled[j]
        shuffled[j] = t
      }
      setPosts(shuffled)
    } catch (error) {
      console.error('获取帖子失败:', error)
      const errorMessage = error instanceof Error ? error.message : '获取帖子失败，请稍后重试'
      toast.error(errorMessage)
      // 即使出错也要显示空状态，不要无限加载
      setPosts([])
    } finally {
      if (fallbackTimer !== null) {
        clearTimeout(fallbackTimer)
      }
      setIsLoading(false)
    }
  }

  useEffect(() => {
    // 组件加载时测试数据库连接
    console.log('HomePage 组件加载，开始测试数据库连接...')
    fetchPosts()
  }, [])

  const handlePostSuccess = () => {
    fetchPosts() // 刷新帖子列表
  }

  const handleEditPost = (post: Post) => {
    setEditingPost(post)
    setIsEditModalOpen(true)
  }

  const handlePostUpdated = (updatedPost: Post) => {
    setPosts(prevPosts => 
      prevPosts.map(post => 
        post.id === updatedPost.id ? updatedPost : post
      )
    )
  }

  const handleDeletePost = (postId: string) => {
    setPosts(prevPosts => prevPosts.filter(post => post.id !== postId))
  }

  // 下拉刷新功能
  const { isPulling, isRefreshing, pullProgress, containerRef } = usePullToRefresh({
    onRefresh: fetchPosts,
    threshold: 80,
    maxPull: 120,
    disabled: isLoading
  })

  if (isLoading) {
    return (
      <div ref={containerRef} className="min-h-screen bg-gray-900 text-white">
        <PullToRefreshIndicator 
          isPulling={isPulling} 
          isRefreshing={isRefreshing} 
          pullProgress={pullProgress} 
        />
        <div className="max-w-4xl mx-auto">
          <div className="grid gap-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-gray-800 rounded-xl p-4 animate-pulse">
                <div className="flex items-center space-x-3 mb-3">
                  <div className="w-10 h-10 bg-gray-700 rounded-full"></div>
                  <div className="space-y-2">
                    <div className="h-3 bg-gray-700 rounded w-20"></div>
                    <div className="h-2 bg-gray-700 rounded w-12"></div>
                  </div>
                </div>
                <div className="space-y-2">
                  <div className="h-3 bg-gray-700 rounded w-full"></div>
                  <div className="h-3 bg-gray-700 rounded w-3/4"></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div ref={containerRef} className="min-h-screen bg-gray-900 text-white">
      <PullToRefreshIndicator 
        isPulling={isPulling} 
        isRefreshing={isRefreshing} 
        pullProgress={pullProgress} 
      />
      
      {/* 顶部导航栏 - 移动端优化 */}
      <header className="sticky top-0 z-10 bg-gray-800 border-b border-gray-700">
        <div className="max-w-4xl mx-auto px-3 sm:px-4 py-2 sm:py-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2 sm:space-x-4">
              <h1 className="text-lg sm:text-xl font-bold whitespace-nowrap">二次元小窝</h1>
              <div className="hidden md:block w-64">
                <SmartSearchBar />
              </div>
            </div>
            <div className="flex items-center space-x-2 sm:space-x-3">
              <button className="p-1 sm:p-2 text-gray-300 hover:text-white transition-colors">
                <Search className="w-4 h-4 sm:w-5 sm:h-5" />
              </button>
              <button
                onClick={() => setIsCreateModalOpen(true)}
                className="bg-blue-600 text-white p-1.5 sm:p-2 rounded-full hover:bg-blue-700 transition-colors"
              >
                <Plus className="w-4 h-4 sm:w-5 sm:h-5" />
              </button>
            </div>
          </div>
          
          {/* 移动端搜索 */}
          <div className="md:hidden mt-2">
            <SmartSearchBar />
          </div>
        </div>
      </header>

      {/* 标签导航 - 移动端优化 */}
      <div className="bg-gray-800 border-b border-gray-700">
        <div className="max-w-4xl mx-auto px-3 sm:px-4">
          <div className="flex space-x-4 sm:space-x-6 py-2 sm:py-3 overflow-x-auto">
            <button
              onClick={() => setActiveTab('following')}
              className={`flex-shrink-0 pb-1 sm:pb-2 border-b-2 font-medium text-sm sm:text-base transition-colors duration-200 ${
                activeTab === 'following'
                  ? 'text-white border-blue-500'
                  : 'text-gray-400 border-transparent hover:text-gray-200'
              }`}
            >
              关注
            </button>
            <button
              onClick={() => setActiveTab('recommended')}
              className={`flex-shrink-0 pb-1 sm:pb-2 border-b-2 font-medium text-sm sm:text-base transition-colors duration-200 ${
                activeTab === 'recommended'
                  ? 'text-white border-blue-500'
                  : 'text-gray-400 border-transparent hover:text-gray-200'
              }`}
            >
              推荐
            </button>
            <button
              onClick={() => setActiveTab('latest')}
              className={`flex-shrink-0 pb-1 sm:pb-2 border-b-2 font-medium text-sm sm:text-base transition-colors duration-200 ${
                activeTab === 'latest'
                  ? 'text-white border-blue-500'
                  : 'text-gray-400 border-transparent hover:text-gray-200'
              }`}
            >
              最新
            </button>
          </div>
        </div>
      </div>

      {/* 分类导航 - 移动端优化 */}
      <div className="bg-gray-800 border-b border-gray-700">
        <div className="max-w-4xl mx-auto px-3 sm:px-4">
          <div className="flex space-x-2 sm:space-x-4 py-2 sm:py-3 overflow-x-auto">
            {[
              { key: 'all', label: '全部' },
              { key: 'dynamic', label: '动态' },
              { key: 'article', label: '文章' },
              { key: 'image', label: '图片' },
              { key: 'novel', label: '小说' },
              { key: 'comic', label: '漫画' }
            ].map((category) => (
              <button
                key={category.key}
                onClick={() => setActiveCategory(category.key as any)}
                className={`flex-shrink-0 px-2 sm:px-3 py-1 rounded-full text-xs sm:text-sm font-medium transition-colors duration-200 ${
                  activeCategory === category.key
                    ? 'bg-blue-600 text-white'
                    : 'text-gray-400 hover:text-gray-200 hover:bg-gray-700'
                }`}
              >
                {category.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* 主要内容 - 移动端优化 */}
      <main className="max-w-4xl mx-auto">
        {/* 标签内容区域 */}
        {activeTab === 'following' && user ? (
          <div className="px-3 sm:px-4 py-3 sm:py-4">
            <FollowedTagsFeed />
          </div>
        ) : (
          <div className="px-3 sm:px-4 py-3 sm:py-4">
            <PopularTags 
              limit={15} 
              showCount={true} 
              showFollowButton={false}
            />
          </div>
        )}

        {/* 帖子列表 */}
        <div className="px-3 sm:px-4 space-y-3 sm:space-y-4">
          {posts.length === 0 ? (
            <div className="text-center py-8 sm:py-12">
              <div className="text-4xl sm:text-6xl mb-3 sm:mb-4">📱</div>
              <h3 className="text-base sm:text-lg font-semibold text-gray-400 mb-1 sm:mb-2">还没有内容</h3>
              <p className="text-gray-500 text-sm">成为第一个分享的人吧！</p>
            </div>
          ) : (
            posts.map((post) => (
              <PostCard 
                key={post.id} 
                post={post} 
                onEdit={handleEditPost}
                onDelete={handleDeletePost}
              />
            ))
          )}
        </div>

        {/* 探索更多内容 */}
        <div className="text-center py-6 sm:py-8">
          <button
            onClick={fetchPosts}
            className="bg-blue-600 text-white px-4 sm:px-6 py-2 rounded-full font-medium hover:bg-blue-700 transition-colors text-sm sm:text-base"
          >
            🔮 探索新世界
          </button>
        </div>
      </main>

      {/* 底部导航 - 移动端优化 */}
      <nav className="fixed bottom-0 left-0 right-0 bg-gray-800 border-t border-gray-700">
        <div className="max-w-4xl mx-auto px-3 sm:px-4 py-2">
          <div className="flex items-center justify-around">
            <button className="flex flex-col items-center space-y-1 py-1 sm:py-2 text-blue-500 transition-colors">
              <Home className="w-4 h-4 sm:w-5 sm:h-5" />
              <span className="text-xs">首页</span>
            </button>
            <button className="flex flex-col items-center space-y-1 py-1 sm:py-2 text-gray-400 hover:text-gray-200 transition-colors">
              <Compass className="w-4 h-4 sm:w-5 sm:h-5" />
              <span className="text-xs">主题</span>
            </button>
            <button
              onClick={() => setIsCreateModalOpen(true)}
              className="bg-blue-600 text-white p-2 sm:p-3 rounded-full -mt-2 sm:-mt-4 hover:bg-blue-700 transition-colors"
            >
              <Plus className="w-5 h-5 sm:w-6 sm:h-6" />
            </button>
            <button className="flex flex-col items-center space-y-1 py-1 sm:py-2 text-gray-400 hover:text-gray-200 transition-colors">
              <MessageCircle className="w-4 h-4 sm:w-5 sm:h-5" />
              <span className="text-xs">消息</span>
            </button>
            <button className="flex flex-col items-center space-y-1 py-1 sm:py-2 text-gray-400 hover:text-gray-200 transition-colors">
              <User className="w-4 h-4 sm:w-5 sm:h-5" />
              <span className="text-xs">我的</span>
            </button>
          </div>
        </div>
      </nav>

      {/* 发布模态框 */}
      <CreatePostModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onSuccess={handlePostSuccess}
      />

      {/* 编辑模态框 */}
      <PostEditModal
        post={editingPost}
        isOpen={isEditModalOpen}
        onClose={() => {
          setIsEditModalOpen(false)
          setEditingPost(null)
        }}
        onSave={handlePostUpdated}
      />
    </div>
  )
}