import { createContext, useContext, useState, useEffect, ReactNode } from 'react'
import { User } from '@supabase/supabase-js'
import { supabase } from '../lib/supabase'
import { useAuthStore } from '../stores/authStore'

interface AuthContextType {
  user: User | null
  isAuthenticated: boolean
  isLoading: boolean
  signOut: () => Promise<void>
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  isAuthenticated: false,
  isLoading: true,
  signOut: async () => {},
})

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const { setUser: setStoreUser, setLoading } = useAuthStore()

  // 确保用户资料存在的函数
  const ensureUserProfile = async (currentUser: User) => {
    try {
      // 检查用户是否已存在于public.users表中
      const { data: existingUser, error: checkError } = await supabase
        .from('users')
        .select('id')
        .eq('id', currentUser.id)
        .single()

      if (checkError && checkError.code !== 'PGRST116') {
        console.error('检查用户资料失败:', checkError)
        return
      }

      // 如果用户不存在，创建用户资料
      if (!existingUser) {
        console.log('创建新用户资料:', currentUser.id)
        const { error: createError } = await supabase
          .from('users')
          .insert({
            id: currentUser.id,
            username: currentUser.email?.split('@')[0] || `user_${Date.now()}`,
            email: currentUser.email,
            avatar_url: currentUser.user_metadata?.avatar_url || null,
            bio: null,
            posts_count: 0,
            followers_count: 0,
            following_count: 0,
            created_at: new Date().toISOString()
          })

        if (createError) {
          console.error('创建用户资料失败:', createError)
        } else {
          console.log('用户资料创建成功')
        }
      }
    } catch (error) {
      console.error('确保用户资料时出错:', error)
    }
  }

  useEffect(() => {
    // 获取当前会话并确保用户资料存在
    supabase.auth.getSession().then(async ({ data: { session } }) => {
      const currentUser = session?.user ?? null
      
      // 如果用户已登录，确保在public.users表中存在记录
      if (currentUser) {
        await ensureUserProfile(currentUser)
      }
      
      setUser(currentUser)
      setStoreUser(currentUser)
      setIsLoading(false)
      setLoading(false)
    }).catch(() => {
      setUser(null)
      setStoreUser(null)
      setIsLoading(false)
      setLoading(false)
    })

    // 监听认证状态变化
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_event, session) => {
      const currentUser = session?.user ?? null
      
      // 如果用户刚登录，确保在public.users表中存在记录
      if (currentUser && _event === 'SIGNED_IN') {
        await ensureUserProfile(currentUser)
      }
      
      setUser(currentUser)
      setStoreUser(currentUser)
      setIsLoading(false)
      setLoading(false)
    })

    return () => {
      subscription.unsubscribe()
    }
  }, [setStoreUser, setLoading])

  const signOut = async () => {
    await supabase.auth.signOut()
    setUser(null)
    setStoreUser(null)
  }

  return (
    <AuthContext.Provider value={{
      user,
      isAuthenticated: !!user,
      isLoading,
      signOut,
    }}>
      {children}
    </AuthContext.Provider>
  )
}

export const useAuth = () => {
  const context = useContext(AuthContext)
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider')
  }
  return context
}