/**
 * 智能搜索组件
 * 提供标签、帖子、用户的自动推荐功能
 */

import { useState, useEffect, useCallback } from 'react'
import { supabase } from '../lib/supabase'
import { useNavigate } from 'react-router-dom'
import { Search, User, Hash, FileText, TrendingUp, Clock, X } from 'lucide-react'

interface SearchRecommendation {
  type: 'tag' | 'post' | 'user'
  id: string
  title: string
  subtitle?: string
  image?: string
  metadata?: any
}

interface SmartSearchBarProps {
  onSearch?: (query: string, type?: string) => void
  placeholder?: string
  showRecommendations?: boolean
}

export function SmartSearchBar({ 
  onSearch, 
  placeholder = "搜索动漫、游戏、Cosplay、用户...",
  showRecommendations = true
}: SmartSearchBarProps) {
  const [query, setQuery] = useState('')
  const [isFocused, setIsFocused] = useState(false)
  const [recommendations, setRecommendations] = useState<SearchRecommendation[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [searchHistory, setSearchHistory] = useState<string[]>([])
  const navigate = useNavigate()

  // 加载搜索历史
  useEffect(() => {
    const history = localStorage.getItem('searchHistory')
    if (history) {
      setSearchHistory(JSON.parse(history))
    }
  }, [])

  // 保存搜索历史
  const saveSearchHistory = useCallback((searchTerm: string) => {
    const newHistory = [searchTerm, ...searchHistory.filter(item => item !== searchTerm)].slice(0, 10)
    setSearchHistory(newHistory)
    localStorage.setItem('searchHistory', JSON.stringify(newHistory))
  }, [searchHistory])

  // 智能搜索推荐
  const fetchRecommendations = useCallback(async (searchQuery: string) => {
    if (!searchQuery.trim() || searchQuery.length < 2) {
      setRecommendations([])
      return
    }

    setIsLoading(true)
    
    try {
      const results: SearchRecommendation[] = []

      // 搜索标签
      const tagPromise = supabase
        .from('tags')
        .select('id, name, usage_count, category')
        .ilike('name', `%${searchQuery}%`)
        .order('usage_count', { ascending: false })
        .limit(5)

      // 搜索帖子内容
      const postPromise = supabase
        .from('posts')
        .select(`
          id, 
          content, 
          images,
          created_at,
          user:users!posts_user_id_fkey(username, avatar_url)
        `)
        .or(`content.ilike.%${searchQuery}%`)
        .order('created_at', { ascending: false })
        .limit(3)

      // 搜索用户
      const userPromise = supabase
        .from('users')
        .select('id, username, display_name, avatar_url, bio')
        .or(`username.ilike.%${searchQuery}%,display_name.ilike.%${searchQuery}%`)
        .order('created_at', { ascending: false })
        .limit(3)

      const [tagResults, postResults, userResults] = await Promise.all([
        tagPromise,
        postPromise,
        userPromise
      ])

      // 处理标签结果
      if (tagResults.data) {
        results.push(...tagResults.data.map(tag => ({
          type: 'tag' as const,
          id: tag.id,
          title: tag.name,
          subtitle: `使用次数: ${tag.usage_count || 0}`,
          metadata: { category: tag.category }
        })))
      }

      // 处理帖子结果
      if (postResults.data) {
        results.push(...postResults.data.map(post => ({
          type: 'post' as const,
          id: post.id,
          title: post.content?.substring(0, 50) + (post.content?.length > 50 ? '...' : '') || '无标题',
          subtitle: `发布者: ${post.user?.[0]?.username || '匿名用户'} `,
          image: post.images?.[0],
          metadata: { created_at: post.created_at }
        })))
      }

      // 处理用户结果
      if (userResults.data) {
        results.push(...userResults.data.map(user => ({
          type: 'user' as const,
          id: user.id,
          title: user.display_name || user.username,
          subtitle: user.bio?.substring(0, 30) + (user.bio?.length > 30 ? '...' : '') || `@${user.username}`,
          image: user.avatar_url,
          metadata: { username: user.username }
        })))
      }

      setRecommendations(results)
    } catch (error) {
      console.error('搜索推荐失败:', error)
      setRecommendations([])
    } finally {
      setIsLoading(false)
    }
  }, [])

  // 防抖搜索
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      if (query.trim() && query.length >= 2) {
        fetchRecommendations(query)
      } else {
        setRecommendations([])
      }
    }, 300)

    return () => clearTimeout(timeoutId)
  }, [query, fetchRecommendations])

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (query.trim()) {
      saveSearchHistory(query.trim())
      onSearch?.(query.trim())
      setIsFocused(false)
    }
  }

  const handleRecommendationClick = (recommendation: SearchRecommendation) => {
    saveSearchHistory(recommendation.title)
    
    switch (recommendation.type) {
      case 'tag':
        navigate(`/tags/${encodeURIComponent(recommendation.title)}`)
        break
      case 'post':
        navigate(`/post/${recommendation.id}`)
        break
      case 'user':
        navigate(`/u/${recommendation.metadata?.username || recommendation.id}`)
        break
    }
    
    setQuery(recommendation.title)
    setIsFocused(false)
    onSearch?.(recommendation.title, recommendation.type)
  }

  const handleHistoryClick = (historyItem: string) => {
    setQuery(historyItem)
    onSearch?.(historyItem)
    setIsFocused(false)
  }

  const clearSearchHistory = () => {
    setSearchHistory([])
    localStorage.removeItem('searchHistory')
  }

  const getIcon = (type: string) => {
    switch (type) {
      case 'tag':
        return <Hash className="w-4 h-4 text-pink-500" />
      case 'post':
        return <FileText className="w-4 h-4 text-blue-500" />
      case 'user':
        return <User className="w-4 h-4 text-green-500" />
      default:
        return <Search className="w-4 h-4 text-gray-400" />
    }
  }

  return (
    <div className="relative w-full max-w-2xl mx-auto">
      <form onSubmit={handleSubmit} className="relative">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 dark:text-gray-500 w-5 h-5" />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setTimeout(() => setIsFocused(false), 200)}
            placeholder={placeholder}
            className="w-full pl-10 pr-10 py-3 bg-white dark:bg-gray-800 bg-opacity-80 dark:bg-opacity-80 backdrop-blur-sm border border-pink-200 dark:border-gray-600 rounded-full focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all duration-200 text-gray-800 dark:text-gray-200"
          />
          {query && (
            <button
              type="button"
              onClick={() => setQuery('')}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      </form>

      {/* 搜索建议和推荐 */}
      {isFocused && showRecommendations && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-gray-800 rounded-2xl shadow-lg border border-pink-100 dark:border-gray-600 p-4 z-50 max-h-96 overflow-y-auto">
          
          {/* 搜索历史 */}
          {searchHistory.length > 0 && !query && (
            <div className="mb-4">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center space-x-2">
                  <Clock className="w-4 h-4 text-gray-500" />
                  <span className="text-sm font-medium text-gray-700 dark:text-gray-200">搜索历史</span>
                </div>
                <button
                  onClick={clearSearchHistory}
                  className="text-xs text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
                >
                  清除
                </button>
              </div>
              <div className="flex flex-wrap gap-2">
                {searchHistory.map((item) => (
                  <button
                    key={item}
                    onClick={() => handleHistoryClick(item)}
                    className="px-3 py-1 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-full text-sm hover:bg-gray-200 dark:hover:bg-gray-600 transition-all duration-200"
                  >
                    {item}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* 智能推荐 */}
          {query && query.length >= 2 && (
            <div className="mb-4">
              <div className="flex items-center space-x-2 mb-3">
                <TrendingUp className="w-4 h-4 text-pink-500" />
                <span className="text-sm font-medium text-gray-700 dark:text-gray-200">智能推荐</span>
                {isLoading && <div className="w-4 h-4 border-2 border-pink-500 border-t-transparent rounded-full animate-spin" />}
              </div>
              
              {recommendations.length > 0 ? (
                <div className="space-y-2">
                  {recommendations.map((rec) => (
                    <button
                      key={`${rec.type}-${rec.id}`}
                      onClick={() => handleRecommendationClick(rec)}
                      className="w-full flex items-center space-x-3 p-3 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-all duration-200 text-left"
                    >
                      <div className="flex-shrink-0">
                        {getIcon(rec.type)}
                      </div>
                      
                      {rec.image && (
                        <img
                          src={rec.image}
                          alt={rec.title}
                          className="w-10 h-10 rounded-lg object-cover flex-shrink-0"
                          onError={(e) => {
                            (e.target as HTMLImageElement).style.display = 'none'
                          }}
                        />
                      )}
                      
                      <div className="flex-1 min-w-0">
                        <div className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
                          {rec.title}
                        </div>
                        {rec.subtitle && (
                          <div className="text-xs text-gray-500 dark:text-gray-400 truncate">
                            {rec.subtitle}
                          </div>
                        )}
                      </div>
                      
                      <div className="text-xs text-gray-400 dark:text-gray-500 capitalize">
                        {rec.type === 'tag' ? '标签' : rec.type === 'post' ? '帖子' : '用户'}
                      </div>
                    </button>
                  ))}
                </div>
              ) : (
                !isLoading && (
                  <div className="text-sm text-gray-500 dark:text-gray-400 text-center py-4">
                    没有找到相关内容
                  </div>
                )
              )}
            </div>
          )}

          {/* 热门标签（当没有输入时显示） */}
          {!query && (
            <div>
              <div className="flex items-center space-x-2 mb-3">
                <TrendingUp className="w-4 h-4 text-pink-500" />
                <span className="text-sm font-medium text-gray-700 dark:text-gray-200">热门标签</span>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {['动漫', '游戏', 'Cosplay', '插画', '手办', '二次元'].map((tag) => (
                  <button
                    key={tag}
                    onClick={() => {
                      saveSearchHistory(tag)
                      navigate(`/tags/${encodeURIComponent(tag)}`)
                      setQuery(tag)
                      setIsFocused(false)
                    }}
                    className="px-3 py-2 bg-pink-100 dark:bg-pink-900 text-pink-700 dark:text-pink-300 rounded-lg text-sm hover:bg-pink-200 dark:hover:bg-pink-800 transition-all duration-200 text-center"
                  >
                    #{tag}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}