import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { Heart, Hash, RefreshCw, Settings } from 'lucide-react'
import { useFollowedTags, useFollowedTagsPosts } from '../hooks/useFollowedTags'
import { PostCard } from './PostCard'
import { EnhancedTag } from './EnhancedTag'
import { toast } from 'sonner'

export function FollowedTagsFeed() {
  const { followedTags, isLoading: tagsLoading, refetch: refetchTags } = useFollowedTags()
  const { posts, isLoading: postsLoading, refetch: refetchPosts } = useFollowedTagsPosts(10)
  const [isRefreshing, setIsRefreshing] = useState(false)

  const handleRefresh = async () => {
    setIsRefreshing(true)
    try {
      await Promise.all([refetchTags(), refetchPosts()])
      toast.success('已刷新关注标签内容')
    } catch (error) {
      toast.error('刷新失败，请重试')
    } finally {
      setIsRefreshing(false)
    }
  }

  const handleTagFollowChange = async (isFollowed: boolean) => {
    // 标签关注状态改变时自动刷新
    await refetchTags()
    await refetchPosts()
  }

  if (tagsLoading) {
    return (
      <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg p-6 mb-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-bold text-gray-800 dark:text-gray-200 flex items-center">
            <Heart className="w-5 h-5 mr-2 text-pink-500" />
            关注的标签
          </h2>
        </div>
        <div className="animate-pulse">
          <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/4 mb-2"></div>
          <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/2"></div>
        </div>
      </div>
    )
  }

  if (followedTags.length === 0) {
    return (
      <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg p-6 mb-6">
        <div className="text-center py-8">
          <Heart className="w-12 h-12 mx-auto mb-4 text-gray-300 dark:text-gray-600" />
          <h3 className="text-lg font-semibold text-gray-600 dark:text-gray-300 mb-2">还没有关注任何标签</h3>
          <p className="text-gray-500 dark:text-gray-400 mb-4">
            关注你感兴趣的标签，获取最新相关内容推送
          </p>
          <Link
            to="/explore"
            className="inline-flex items-center px-4 py-2 bg-pink-500 hover:bg-pink-600 text-white rounded-full font-medium transition-colors"
          >
            <Hash className="w-4 h-4 mr-2" />
            探索标签
          </Link>
        </div>
      </div>
    )
  }

  return (
    <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg p-6 mb-6">
      {/* 头部 */}
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-bold text-gray-800 dark:text-gray-200 flex items-center">
          <Heart className="w-5 h-5 mr-2 text-pink-500" />
          关注的标签
          <span className="ml-2 text-sm font-normal text-gray-500 dark:text-gray-400">
            ({followedTags.length})
          </span>
        </h2>
        <div className="flex items-center space-x-2">
          <button
            onClick={handleRefresh}
            disabled={isRefreshing}
            className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors disabled:opacity-50"
            title="刷新内容"
          >
            <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
          </button>
          <Link
            to="/settings/tags"
            className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
            title="管理关注的标签"
          >
            <Settings className="w-4 h-4" />
          </Link>
        </div>
      </div>

      {/* 关注的标签列表 */}
      <div className="mb-6">
        <div className="flex flex-wrap gap-2 mb-4">
          {followedTags.slice(0, 8).map((tag) => (
            <EnhancedTag
              key={tag.id}
              id={tag.id}
              name={tag.name}
              usageCount={tag.usage_count}
              followersCount={tag.followers_count}
              category={tag.category}
              size="sm"
              showStats={true}
              showFollowButton={true}
              onFollowChange={handleTagFollowChange}
            />
          ))}
          {followedTags.length > 8 && (
            <Link
              to="/settings/tags"
              className="px-3 py-1 text-sm bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-full hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
            >
              +{followedTags.length - 8} 更多
            </Link>
          )}
        </div>
      </div>

      {/* 相关帖子 */}
      <div>
        <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-3 flex items-center">
          <Hash className="w-4 h-4 mr-2" />
          最新相关内容
        </h3>
        
        {postsLoading ? (
          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-gray-50 dark:bg-gray-700 rounded-2xl p-4 animate-pulse">
                <div className="h-4 bg-gray-200 dark:bg-gray-600 rounded w-3/4 mb-2"></div>
                <div className="h-4 bg-gray-200 dark:bg-gray-600 rounded w-1/2"></div>
              </div>
            ))}
          </div>
        ) : posts.length > 0 ? (
          <div className="space-y-4">
            {posts.slice(0, 3).map((post) => (
              <PostCard key={post.id} post={post} />
            ))}
            {posts.length > 3 && (
              <div className="text-center">
                <Link
                  to="/feed"
                  className="inline-flex items-center px-4 py-2 text-pink-600 hover:text-pink-700 dark:text-pink-400 dark:hover:text-pink-300 font-medium"
                >
                  查看更多内容
                  <Hash className="w-4 h-4 ml-1" />
                </Link>
              </div>
            )}
          </div>
        ) : (
          <div className="text-center py-6">
            <div className="text-gray-500 dark:text-gray-400 mb-2">暂无相关内容</div>
            <div className="text-sm text-gray-400 dark:text-gray-500">
              关注更多标签以获取更丰富内容
            </div>
          </div>
        )}
      </div>
    </div>
  )
}