import { RefreshCw } from 'lucide-react'

interface PullToRefreshIndicatorProps {
  isPulling: boolean
  isRefreshing: boolean
  pullProgress: number
  threshold?: number
}

export function PullToRefreshIndicator({ 
  isPulling, 
  isRefreshing, 
  pullProgress, 
  threshold = 80 
}: PullToRefreshIndicatorProps) {
  if (!isPulling && !isRefreshing) return null

  const progress = Math.min(pullProgress / threshold, 1)
  const rotation = isRefreshing ? 360 : progress * 180

  return (
    <div className="fixed top-0 left-0 right-0 z-50 pointer-events-none">
      <div 
        className="flex justify-center items-center transition-all duration-300"
        style={{ 
          height: `${Math.min(pullProgress, threshold + 20)}px`,
          opacity: isPulling || isRefreshing ? 1 : 0
        }}
      >
        <div className="bg-white dark:bg-gray-800 rounded-full p-3 shadow-lg border border-gray-200 dark:border-gray-700">
          <RefreshCw 
            className={`w-6 h-6 text-pink-500 dark:text-pink-400 transition-transform duration-300 ${
              isRefreshing ? 'animate-spin' : ''
            }`}
            style={{ transform: `rotate(${rotation}deg)` }}
          />
        </div>
      </div>
    </div>
  )
}