// 数据库错误处理工具
export function handleDatabaseError(error: any, context: string) {
  console.error(`Database error in ${context}:`, error)
  
  // 常见的数据库错误处理
  if (error?.code) {
    switch (error.code) {
      case 'PGRST116':
        return '请求的数据不存在'
      case 'PGRST301':
        return '没有权限访问此数据'
      case '23505':
        return '数据已存在，请勿重复操作'
      case '23503':
        return '关联数据不存在'
      default:
        return error.message || '数据库操作失败'
    }
  }
  
  return '操作失败，请稍后重试'
}

// 检查数据库连接状态
export async function checkDatabaseConnection(supabase: any) {
  try {
    const { data, error } = await supabase
      .from('users')
      .select('id')
      .limit(1)
    
    if (error) {
      console.error('Database connection check failed:', error)
      return false
    }
    
    return true
  } catch (error) {
    console.error('Database connection error:', error)
    return false
  }
}